    fn intersect_sorted_node_sets(
        &self,
        request: &ResidentMultiwayIntersectionRequest,
        cancellation: &CancellationToken,
    ) -> Result<Vec<u32>> {
        if !self.resident.contains_key(&request.project) {
            return Err(project_not_resident(request.project));
        }
        let Some(first) = request.sorted_sets.first() else {
            return Ok(Vec::new());
        };
        let mut intersection = first.clone();
        intersection.sort_unstable();
        intersection.dedup();
        for candidate in request.sorted_sets.iter().skip(1) {
            ensure_not_cancelled(cancellation)?;
            let mut candidate = candidate.clone();
            candidate.sort_unstable();
            candidate.dedup();
            let mut next = Vec::with_capacity(intersection.len().min(candidate.len()));
            let (mut left, mut right) = (0, 0);
            while left < intersection.len() && right < candidate.len() {
                if (left + right) & 4095 == 0 {
                    ensure_not_cancelled(cancellation)?;
                }
                match intersection[left].cmp(&candidate[right]) {
                    std::cmp::Ordering::Less => left += 1,
                    std::cmp::Ordering::Greater => right += 1,
                    std::cmp::Ordering::Equal => {
                        next.push(intersection[left]);
                        left += 1;
                        right += 1;
                    }
                }
            }
            intersection = next;
            if intersection.is_empty() {
                break;
            }
        }
        if intersection.len() > request.max_output_rows {
            return Err(Error::new(
                ErrorCode::ResultBudgetExceeded,
                "cyclic multiway intersection exceeded the row budget",
            ));
        }
        Ok(intersection)
    }

    fn search_vectors(
        &self,
        request: &ResidentVectorQuery,
        cancellation: &CancellationToken,
    ) -> Result<ResidentVectorResult> {
        if request.access != ResidentVectorAccess::Exact {
            return Err(Error::new(
                ErrorCode::IndexUnavailable,
                "CPU resident execution was asked to substitute for an IVF-PQ physical plan",
            ));
        }
        let resident = self
            .resident
            .get(&request.project)
            .ok_or_else(|| project_not_resident(request.project))?;
        let vector = resident
            .image
            .indexes
            .vectors
            .iter()
            .find(|column| column.property == request.property)
            .ok_or_else(|| {
                Error::new(ErrorCode::IndexUnavailable, "vector column is not resident")
            })?;
        let profile = resident.image.indexes.profile.clone().ok_or_else(|| {
            Error::new(
                ErrorCode::EmbeddingProfileMismatch,
                "resident vector column has no embedding profile",
            )
        })?;
        if profile.dimension as usize != vector.dimension
            || profile.dtype != vector.dtype
            || profile.similarity != vector.similarity
        {
            return Err(Error::new(
                ErrorCode::EmbeddingProfileMismatch,
                "resident vector column and embedding profile differ",
            ));
        }
        validate_vector_queries(request, vector.dimension)?;
        let matrix = decode_vectors(vector);
        let relationship_owned = request.property == crate::graph::SEMANTIC_RELATIONSHIP_PROPERTY;
        if relationship_owned && request.selection.is_some() {
            return Err(Error::new(
                ErrorCode::QueryType,
                "relationship vector search cannot use a node selection",
            ));
        }
        let selected_rows = request
            .selection
            .as_ref()
            .map(|selection| {
                if selection.project != request.project || selection.layers != request.layers {
                    return Err(Error::new(
                        ErrorCode::GpuAdmissionFailure,
                        "vector candidate stage targets a different project or layer mask",
                    ));
                }
                self.execute_node_pipeline(selection, cancellation)
                    .map(|result| {
                        result
                            .start_rows
                            .into_iter()
                            .collect::<std::collections::BTreeSet<_>>()
                    })
            })
            .transpose()?;
        let allowed_entities = request.allowed_entities.as_ref().map(|ids| {
            ids.iter()
                .copied()
                .collect::<std::collections::BTreeSet<_>>()
        });
        let layer_active = vector
            .entity_ids
            .iter()
            .map(|entity| {
                if allowed_entities
                    .as_ref()
                    .is_some_and(|allowed| !allowed.contains(entity))
                {
                    return Ok(0);
                }
                if relationship_owned {
                    let Some(row) = stable_id_row(&resident.edge_id_rows, *entity) else {
                        return Ok(0);
                    };
                    return resident.active_delete_edge(*row).map(|edge| {
                        u8::from(
                            resident.edge_is_visible(*row, &[], request.layers)
                                && edge.is_some_and(|(_, source, target)| {
                                    resident.node_is_visible(source, &[], request.layers)
                                        && resident.node_is_visible(target, &[], request.layers)
                                }),
                        )
                    });
                }
                Ok(u8::from(
                    stable_id_row(&resident.node_id_rows, *entity).is_some_and(|row| {
                        resident.node_is_visible(*row, &[], request.layers)
                            && selected_rows
                                .as_ref()
                                .is_none_or(|selected| selected.contains(row))
                    }),
                ))
            })
            .collect::<Result<Vec<_>>>()?;
        let mut hits = Vec::with_capacity(request.query_count);
        for query_row in 0..request.query_count {
            ensure_not_cancelled(cancellation)?;
            let start = query_row * vector.dimension;
            let mut query = request.queries[start..start + vector.dimension].to_vec();
            prepare_vector_query(vector.similarity, &mut query)?;
            hits.push(score_vectors(
                &matrix,
                vector,
                &query,
                request.limit,
                Some(&layer_active),
                cancellation,
            )?);
        }
        Ok(ResidentVectorResult {
            project: request.project,
            bookmark: resident.bookmark,
            profile,
            similarity: vector.similarity,
            hits,
            approximate_candidates: false,
            access: ResidentVectorAccess::Exact,
            candidate_budget: 0,
            build_generation: [0_u8; 32],
        })
    }

    fn sort_rows(
        &self,
        request: &ResidentSortRequest,
        cancellation: &CancellationToken,
    ) -> Result<ResidentSortResult> {
        request.validate()?;
        ensure_not_cancelled(cancellation)?;
        let mut positions = (0..request.row_count).collect::<Vec<_>>();
        if let Ok((rows, property, key)) = request.single_node_property() {
            let resident = self
                .resident
                .get(&request.project)
                .ok_or_else(|| project_not_resident(request.project))?;
            let values = resident.integer_values(rows, property, cancellation)?;
            positions.sort_by(|left, right| {
                let order = match (values[*left], values[*right]) {
                    (None, None) => std::cmp::Ordering::Equal,
                    (None, Some(_)) => {
                        if key.nulls_first {
                            std::cmp::Ordering::Less
                        } else {
                            std::cmp::Ordering::Greater
                        }
                    }
                    (Some(_), None) => {
                        if key.nulls_first {
                            std::cmp::Ordering::Greater
                        } else {
                            std::cmp::Ordering::Less
                        }
                    }
                    (Some(left), Some(right)) => {
                        let order = left.cmp(&right);
                        if key.descending {
                            order.reverse()
                        } else {
                            order
                        }
                    }
                };
                order.then_with(|| left.cmp(right))
            });
        } else {
            for key in request.keys.iter().rev() {
                let super::ResidentSortSource::Materialized(column) = &key.source else {
                    return Err(Error::new(
                        ErrorCode::GpuAdmissionFailure,
                        "CPU reference cannot combine resident and materialized sort sources",
                    ));
                };
                positions
                    .sort_by(|left, right| compare_materialized_order(column, *left, *right, key));
            }
        }
        ensure_not_cancelled(cancellation)?;
        positions.truncate(
            request
                .limit
                .unwrap_or(positions.len())
                .min(positions.len()),
        );
        Ok(ResidentSortResult {
            positions: positions
                .into_iter()
                .map(|position| {
                    u32::try_from(position).map_err(|_| {
                        Error::new(
                            ErrorCode::ResultBudgetExceeded,
                            "sort input position exceeds u32",
                        )
                    })
                })
                .collect::<Result<_>>()?,
        })
    }

    fn join_node_i64(
        &self,
        request: &ResidentJoinRequest,
        cancellation: &CancellationToken,
    ) -> Result<Vec<ResidentJoinPair>> {
        let resident = self
            .resident
            .get(&request.project)
            .ok_or_else(|| project_not_resident(request.project))?;
        let left =
            resident.integer_values(&request.left_rows, request.left_property, cancellation)?;
        let right =
            resident.integer_values(&request.right_rows, request.right_property, cancellation)?;
        let mut pairs = Vec::new();
        for (left_position, left_value) in left.iter().enumerate() {
            if left_position & 1023 == 0 {
                ensure_not_cancelled(cancellation)?;
            }
            let Some(left_value) = left_value else {
                continue;
            };
            for (right_position, right_value) in right.iter().enumerate() {
                if right_value != &Some(*left_value) {
                    continue;
                }
                if pairs.len() >= request.max_pairs {
                    return Err(Error::new(
                        ErrorCode::ResultBudgetExceeded,
                        "resident equality join exceeded its pair budget",
                    ));
                }
                pairs.push(ResidentJoinPair {
                    left_position: u32::try_from(left_position).map_err(|_| {
                        Error::new(
                            ErrorCode::ResultBudgetExceeded,
                            "join left input position exceeds u32",
                        )
                    })?,
                    right_position: u32::try_from(right_position).map_err(|_| {
                        Error::new(
                            ErrorCode::ResultBudgetExceeded,
                            "join right input position exceeds u32",
                        )
                    })?,
                });
            }
        }
        Ok(pairs)
    }

    fn group_node_i64(
        &self,
        request: &ResidentGroupRequest,
        cancellation: &CancellationToken,
    ) -> Result<Vec<ResidentGroup>> {
        let resident = self
            .resident
            .get(&request.project)
            .ok_or_else(|| project_not_resident(request.project))?;
        let keys = resident.integer_values(&request.rows, request.key_property, cancellation)?;
        let values =
            resident.integer_values(&request.rows, request.value_property, cancellation)?;
        let mut groups = BTreeMap::<Option<i64>, IntegerAggregateState>::new();
        for (position, (key, value)) in keys.into_iter().zip(values).enumerate() {
            if position & 4095 == 0 {
                ensure_not_cancelled(cancellation)?;
            }
            groups
                .entry(key)
                .or_default()
                .push(value, request.aggregate)?;
        }
        groups
            .into_iter()
            .map(|(key, state)| {
                Ok(ResidentGroup {
                    key,
                    rows: state.rows,
                    value: state.finish(request.aggregate),
                })
            })
            .collect()
    }

    fn execute_node_pipeline(
        &self,
        request: &ResidentNodePipelineRequest,
        cancellation: &CancellationToken,
    ) -> Result<ResidentNodePipelineResult> {
        ensure_not_cancelled(cancellation)?;
        request.validate_mutation()?;
        let resident = self
            .resident
            .get(&request.project)
            .ok_or_else(|| project_not_resident(request.project))?;
        let expansion_count = request.expansion_steps().count();
        let relationship_count = request.relationship_column_count();
        let maximum_rows =
            request.maximum_pipeline_rows(resident.node_capacity, resident.edge_capacity)?;
        let projected_width = request
            .integer_projections
            .len()
            .saturating_mul(size_of::<i64>() + size_of::<u8>())
            .saturating_add(request.property_null_projections.len())
            .saturating_add(
                relationship_count
                    .saturating_mul(2)
                    .saturating_mul(size_of::<u32>()),
            );
        let input_rows = resident
            .node_capacity
            .checked_add(maximum_rows)
            .ok_or_else(|| {
                Error::new(
                    ErrorCode::ResultBudgetExceeded,
                    "CPU resident-pipeline scratch row count overflow",
                )
            })?;
        let pipeline_scratch = operator_scratch_bytes(
            input_rows,
            96,
            maximum_rows,
            projected_width.saturating_add(size_of::<u32>()),
        )?;
        let scratch_bytes = pipeline_scratch
            .checked_add(request.mutation_continuation_scratch_bytes()?)
            .ok_or_else(|| {
                Error::new(
                    ErrorCode::ResultBudgetExceeded,
                    "CPU mutation continuation scratch reservation overflow",
                )
            })?;
        let _scratch = self.governor.reserve_scratch(scratch_bytes)?;

        // A mandatory read-only MATCH can apply predicates bound solely to its start node before
        // traversal. This is the delta path for selective graph reads: expansion work tracks the
        // matching starts instead of every unrelated node in the resident graph. Mutation and
        // OPTIONAL pipelines retain their ordered selection semantics below.
        let push_start_predicates = request.mutation.is_none() && !request.initial_optional;
        let start_predicates = request
            .predicates
            .iter()
            .filter(|predicate| predicate.binding == super::ResidentNodeBinding::Start)
            .collect::<Vec<_>>();
        let mut consumed_start_predicates = 0_usize;
        let mut initial_rows = if push_start_predicates && !start_predicates.is_empty() {
            let predicate = start_predicates[0];
            consumed_start_predicates = 1;
            let mut rows = self.filter_node_i64(
                request.project,
                predicate.property,
                predicate.operation,
                predicate.operand,
                cancellation,
            )?;
            let mut retained = 0_usize;
            for position in 0..rows.len() {
                let row = rows[position];
                if resident.node_is_visible(row, &request.labels, request.layers) {
                    rows[retained] = row;
                    retained += 1;
                }
            }
            rows.truncate(retained);
            rows
        } else {
            let first_label = request.labels.first().copied();
            let rows =
                self.scan_nodes(request.project, first_label, request.layers, cancellation)?;
            if request.labels.len() <= 1 {
                // `scan_nodes` already checked activity, layer visibility, and its sole label.
                rows
            } else {
                rows.into_iter()
                    .filter(|row| resident.node_is_visible(*row, &request.labels, request.layers))
                    .collect::<Vec<_>>()
            }
        };
        for predicate in start_predicates.into_iter().skip(consumed_start_predicates) {
            let mut retained = 0_usize;
            for position in 0..initial_rows.len() {
                if position & 4095 == 0 {
                    ensure_not_cancelled(cancellation)?;
                }
                let row = initial_rows[position];
                if resident
                    .integer_value(row, predicate.property)?
                    .is_some_and(|value| compare_i64(value, predicate.operation, predicate.operand))
                {
                    initial_rows[retained] = row;
                    retained += 1;
                }
            }
            initial_rows.truncate(retained);
        }
        if request.initial_optional && expansion_count == 0 && initial_rows.is_empty() {
            initial_rows.push(super::RESIDENT_NULL_ROW);
        }
        let mutation_continuation = request
            .mutation
            .as_ref()
            .and_then(|program| program.continuation.as_ref());
        let mut dependency_start_rows = initial_rows.clone();
        if let Some(continuation) = mutation_continuation {
            for predicate in &continuation.initial_dependency_predicates {
                let values = resident.integer_values(
                    &dependency_start_rows,
                    predicate.property,
                    cancellation,
                )?;
                dependency_start_rows = dependency_start_rows
                    .into_iter()
                    .zip(values)
                    .filter_map(|(row, value)| {
                        value
                            .is_some_and(|value| {
                                compare_i64(value, predicate.operation, predicate.operand)
                            })
                            .then_some(row)
                    })
                    .collect();
            }
        } else {
            dependency_start_rows.clear();
        }
        let dependency_start_rows = dependency_start_rows.into_iter().collect::<BTreeSet<_>>();
        let mut mutation_read_dependencies = mutation_continuation.map(|_| {
            dependency_start_rows
                .iter()
                .copied()
                .filter(|row| *row != super::RESIDENT_NULL_ROW)
                .map(ResidentMutationReadDependency::Node)
                .collect::<BTreeSet<_>>()
        });
        let mutation_filter_stages = request.mutation_filter_stages()?;
        let mut filter_cardinalities = Vec::with_capacity(mutation_filter_stages.len());
        let mut node_rows = vec![initial_rows];
        let mut relationship_rows: Vec<Vec<u32>> = Vec::new();
        for (step_index, expansion) in request.expansion_steps().enumerate() {
            if expansion.optional && step_index + 1 != expansion_count {
                return Err(Error::new(
                    ErrorCode::GpuAdmissionFailure,
                    "only the final resident path expansion may be OPTIONAL",
                ));
            }
            let input_ends = node_rows
                .last()
                .cloned()
                .ok_or_else(|| Error::internal("resident path has no source node column"))?;
            let mut source_positions = Vec::new();
            let mut next_edges = Vec::new();
            let mut next_ends = Vec::new();
            let predicate_cardinality_base = filter_cardinalities.len();
            filter_cardinalities.extend(std::iter::repeat_n(
                (0_usize, 0_usize),
                expansion.end_predicates.len(),
            ));
            for (position, input_start) in input_ends.into_iter().enumerate() {
                if position & 4095 == 0 {
                    ensure_not_cancelled(cancellation)?;
                }
                let expanded = match expansion.direction {
                    super::ResidentDirection::Outgoing => self
                        .expand_project_out(request.project, &[input_start], cancellation)?
                        .into_iter()
                        .map(|(_, target, edge)| (target, edge))
                        .collect(),
                    super::ResidentDirection::Incoming => self
                        .expand_project_in(request.project, &[input_start], cancellation)?
                        .into_iter()
                        .map(|(source, _, edge)| (source, edge))
                        .collect(),
                    super::ResidentDirection::Undirected => {
                        let mut rows = self
                            .expand_project_out(request.project, &[input_start], cancellation)?
                            .into_iter()
                            .map(|(_, target, edge)| (target, edge))
                            .collect::<Vec<_>>();
                        rows.extend(
                            self.expand_project_in(request.project, &[input_start], cancellation)?
                                .into_iter()
                                .filter_map(|(source, target, edge)| {
                                    // A self-loop occurs in both adjacency directions but is one
                                    // undirected match from its sole endpoint.
                                    (source != target).then_some((source, edge))
                                }),
                        );
                        rows
                    }
                };
                let first_match = next_ends.len();
                for (end, edge) in expanded {
                    // Generic MATCH records a traversed edge and neighbor after relationship and
                    // path-uniqueness checks, but before the end-node pattern is tested. Preserve
                    // that exact dependency boundary even when this candidate produces no row.
                    let reuses_relationship = relationship_rows.iter().any(|prior| {
                        prior
                            .get(position)
                            .is_some_and(|previous| *previous == edge)
                    });
                    if !resident.edge_is_visible(
                        edge,
                        &expansion.relationship_types,
                        request.layers,
                    ) || !resident.node_is_visible(end, &[], request.layers)
                        || reuses_relationship
                    {
                        continue;
                    }
                    let dependency_start = node_rows
                        .first()
                        .and_then(|rows| rows.get(position))
                        .is_some_and(|row| dependency_start_rows.contains(row));
                    if dependency_start
                        && let Some(dependencies) = mutation_read_dependencies.as_mut()
                    {
                        dependencies.insert(ResidentMutationReadDependency::Node(end));
                        dependencies.insert(ResidentMutationReadDependency::Relationship(edge));
                    }
                    if !resident.node_is_visible(end, &expansion.end_labels, request.layers)
                        || (expansion.end_equals_start && input_start != end)
                    {
                        continue;
                    }
                    let mut matches_properties = true;
                    for (predicate_index, predicate) in expansion.end_predicates.iter().enumerate()
                    {
                        if predicate.binding != super::ResidentNodeBinding::End {
                            return Err(Error::internal(
                                "optional expansion contains a non-end predicate",
                            ));
                        }
                        let value = resident.integer_value(end, predicate.property)?;
                        let matches = value.is_some_and(|value| {
                            compare_i64(value, predicate.operation, predicate.operand)
                        });
                        record_mutation_filter_cardinality(
                            &mut filter_cardinalities,
                            predicate_cardinality_base.saturating_add(predicate_index),
                            matches,
                        )?;
                        if !matches {
                            matches_properties = false;
                            break;
                        }
                    }
                    if !matches_properties {
                        continue;
                    }
                    source_positions.push(position);
                    next_edges.push(edge);
                    next_ends.push(end);
                }
                if expansion.optional && first_match == next_ends.len() {
                    source_positions.push(position);
                    next_edges.push(super::RESIDENT_NULL_ROW);
                    next_ends.push(super::RESIDENT_NULL_ROW);
                }
            }
            if next_ends.len() > maximum_rows {
                return Err(Error::new(
                    ErrorCode::ResultBudgetExceeded,
                    "resident path expansion exceeded admitted scratch capacity",
                ));
            }
            select_pipeline_rows(&mut node_rows, &mut relationship_rows, &source_positions)?;
            relationship_rows.push(next_edges);
            node_rows.push(next_ends);
        }
        if request.initial_optional
            && expansion_count != 0
            && node_rows.last().is_some_and(Vec::is_empty)
        {
            node_rows = (0..=expansion_count)
                .map(|_| vec![super::RESIDENT_NULL_ROW])
                .collect();
            relationship_rows = (0..expansion_count)
                .map(|_| vec![super::RESIDENT_NULL_ROW])
                .collect();
        }
        if let Some(correlated) = &request.correlated_optional {
            if correlated.expansion.optional {
                return Err(Error::new(
                    ErrorCode::GpuAdmissionFailure,
                    "correlated resident expansion must defer optional null extension to its join stage",
                ));
            }
            let input_sources =
                resident_pipeline_node_rows(&node_rows, correlated.source)?.to_vec();
            let input_targets =
                resident_pipeline_node_rows(&node_rows, correlated.target)?.to_vec();
            if input_sources.len() != input_targets.len() {
                return Err(Error::internal(
                    "correlated resident path bindings have different row counts",
                ));
            }
            let mut source_positions = Vec::new();
            let mut optional_edges = Vec::new();
            let predicate_cardinality_base = filter_cardinalities.len();
            filter_cardinalities.extend(std::iter::repeat_n(
                (0_usize, 0_usize),
                correlated.expansion.end_predicates.len(),
            ));
            for (position, (source, target)) in
                input_sources.into_iter().zip(input_targets).enumerate()
            {
                if position & 4095 == 0 {
                    ensure_not_cancelled(cancellation)?;
                }
                let first_match = optional_edges.len();
                if source != super::RESIDENT_NULL_ROW && target != super::RESIDENT_NULL_ROW {
                    let expanded = match correlated.expansion.direction {
                        super::ResidentDirection::Outgoing => self
                            .expand_project_out(request.project, &[source], cancellation)?
                            .into_iter()
                            .map(|(_, end, edge)| (end, edge))
                            .collect(),
                        super::ResidentDirection::Incoming => self
                            .expand_project_in(request.project, &[source], cancellation)?
                            .into_iter()
                            .map(|(end, _, edge)| (end, edge))
                            .collect(),
                        super::ResidentDirection::Undirected => {
                            let mut rows = self
                                .expand_project_out(request.project, &[source], cancellation)?
                                .into_iter()
                                .map(|(_, end, edge)| (end, edge))
                                .collect::<Vec<_>>();
                            rows.extend(
                                self.expand_project_in(request.project, &[source], cancellation)?
                                    .into_iter()
                                    .filter_map(|(end, input, edge)| {
                                        (end != input).then_some((end, edge))
                                    }),
                            );
                            rows
                        }
                    };
                    for (end, edge) in expanded {
                        if end != target
                            || !resident.edge_is_visible(
                                edge,
                                &correlated.expansion.relationship_types,
                                request.layers,
                            )
                            || !resident.node_is_visible(
                                end,
                                &correlated.expansion.end_labels,
                                request.layers,
                            )
                            || (correlated.expansion.end_equals_start && source != end)
                        {
                            continue;
                        }
                        let mut matches_properties = true;
                        for (predicate_index, predicate) in
                            correlated.expansion.end_predicates.iter().enumerate()
                        {
                            if predicate.binding != super::ResidentNodeBinding::End {
                                return Err(Error::internal(
                                    "correlated expansion contains a non-end predicate",
                                ));
                            }
                            let value = resident.integer_value(end, predicate.property)?;
                            let matches = value.is_some_and(|value| {
                                compare_i64(value, predicate.operation, predicate.operand)
                            });
                            record_mutation_filter_cardinality(
                                &mut filter_cardinalities,
                                predicate_cardinality_base.saturating_add(predicate_index),
                                matches,
                            )?;
                            if !matches {
                                matches_properties = false;
                                break;
                            }
                        }
                        if matches_properties {
                            source_positions.push(position);
                            optional_edges.push(edge);
                        }
                    }
                }
                if first_match == optional_edges.len() {
                    source_positions.push(position);
                    optional_edges.push(super::RESIDENT_NULL_ROW);
                }
            }
            if optional_edges.len() > maximum_rows {
                return Err(Error::new(
                    ErrorCode::ResultBudgetExceeded,
                    "correlated resident optional expansion exceeded admitted scratch capacity",
                ));
            }
            select_pipeline_rows(&mut node_rows, &mut relationship_rows, &source_positions)?;
            relationship_rows.push(optional_edges);
        }
        let selection_input_rows = node_rows.first().map_or(0, Vec::len);
        if let Some(expect_null) = request.relationship_null_filter {
            let input_cardinality = node_rows.first().map_or(0, Vec::len);
            let relationships = relationship_rows.last().ok_or_else(|| {
                Error::new(
                    ErrorCode::QueryType,
                    "resident relationship null filter has no relationship binding",
                )
            })?;
            let selected = relationships
                .iter()
                .enumerate()
                .filter_map(|(position, relationship)| {
                    ((*relationship == super::RESIDENT_NULL_ROW) == expect_null).then_some(position)
                })
                .collect::<Vec<_>>();
            select_pipeline_rows(&mut node_rows, &mut relationship_rows, &selected)?;
            filter_cardinalities.push((input_cardinality, node_rows.first().map_or(0, Vec::len)));
        }
        for predicate in request.predicates.iter().filter(|predicate| {
            !(push_start_predicates && predicate.binding == super::ResidentNodeBinding::Start)
        }) {
            let input_cardinality = node_rows.first().map_or(0, Vec::len);
            let binding_rows = resident_pipeline_node_rows(&node_rows, predicate.binding)?;
            let values = resident.integer_values(binding_rows, predicate.property, cancellation)?;
            let selected = values
                .into_iter()
                .enumerate()
                .filter_map(|(position, value)| {
                    value
                        .is_some_and(|value| {
                            compare_i64(value, predicate.operation, predicate.operand)
                        })
                        .then_some(position)
                })
                .collect::<Vec<_>>();
            select_pipeline_rows(&mut node_rows, &mut relationship_rows, &selected)?;
            filter_cardinalities.push((input_cardinality, node_rows.first().map_or(0, Vec::len)));
        }
        for program in &request.property_filters {
            program.validate()?;
            let row_count = node_rows.first().map_or(0, Vec::len);
            let mut selected = Vec::new();
            for position in 0..row_count {
                if position & 4095 == 0 {
                    ensure_not_cancelled(cancellation)?;
                }
                if cpu_property_filter_value(resident, &node_rows, program, position)? == 2 {
                    selected.push(position);
                }
            }
            select_pipeline_rows(&mut node_rows, &mut relationship_rows, &selected)?;
            filter_cardinalities.push((row_count, node_rows.first().map_or(0, Vec::len)));
        }
        let mut value_left_indices = Vec::new();
        let mut value_right_indices = Vec::new();
        if let Some(matrix) = &request.value_matrix {
            matrix.validate()?;
            let row_count = node_rows.first().map_or(0, Vec::len);
            let pair_count = matrix
                .values
                .len()
                .checked_mul(matrix.values.len())
                .ok_or_else(|| {
                    Error::new(
                        ErrorCode::ResultBudgetExceeded,
                        "resident value matrix pair count overflow",
                    )
                })?;
            let capacity = row_count.checked_mul(pair_count).ok_or_else(|| {
                Error::new(
                    ErrorCode::ResultBudgetExceeded,
                    "resident value matrix row count overflow",
                )
            })?;
            let mut source_positions = Vec::with_capacity(capacity);
            value_left_indices.reserve(capacity);
            value_right_indices.reserve(capacity);
            for source in 0..row_count {
                if source & 4095 == 0 {
                    ensure_not_cancelled(cancellation)?;
                }
                for (left, left_value) in matrix.values.iter().enumerate() {
                    for (right, right_value) in matrix.values.iter().enumerate() {
                        if matrix.exclude_same_index && left == right {
                            continue;
                        }
                        if cpu_value_matrix_compare(left_value, right_value, matrix.comparison) == 2
                        {
                            source_positions.push(source);
                            value_left_indices.push(u32::try_from(left).map_err(|_| {
                                Error::new(
                                    ErrorCode::ResultBudgetExceeded,
                                    "resident value matrix left index exceeds u32",
                                )
                            })?);
                            value_right_indices.push(u32::try_from(right).map_err(|_| {
                                Error::new(
                                    ErrorCode::ResultBudgetExceeded,
                                    "resident value matrix right index exceeds u32",
                                )
                            })?);
                        }
                    }
                }
            }
            select_pipeline_rows(&mut node_rows, &mut relationship_rows, &source_positions)?;
            filter_cardinalities.push((row_count, node_rows.first().map_or(0, Vec::len)));
        }
        let mutation_rows = node_rows.first().map_or(0, Vec::len);
        if request.mutation.is_some() && mutation_rows > request.max_output_rows {
            return Err(Error::new(
                ErrorCode::ResultBudgetExceeded,
                "resident mutation selection exceeded the configured execution-row budget",
            ));
        }
        let mutation_read_dependencies = mutation_read_dependencies
            .map(BTreeSet::into_iter)
            .map(Iterator::collect::<Vec<_>>)
            .unwrap_or_default();
        if mutation_continuation.is_some_and(|continuation| {
            mutation_read_dependencies.len() > continuation.maximum_read_dependencies
        }) {
            return Err(Error::new(
                ErrorCode::ResultBudgetExceeded,
                "resident mutation read dependencies exceeded their admitted capacity",
            ));
        }
        let mutation = request
            .mutation
            .as_ref()
            .map(|program| {
                execute_cpu_mutation_program(
                    resident,
                    program,
                    &node_rows,
                    &relationship_rows,
                    selection_input_rows,
                    &filter_cardinalities,
                    mutation_read_dependencies,
                    cancellation,
                )
            })
            .transpose()?;
        for order in request.orders.iter().rev() {
            let binding_rows = resident_pipeline_node_rows(&node_rows, order.binding)?;
            let cold_positions = if resident.nodes.len() == 0 {
                match resident.image.graph.node_properties.column(order.property) {
                    Some(TypedColumn::Integer { .. }) => Some(stable_nullable_positions(
                        &resident.integer_values(binding_rows, order.property, cancellation)?,
                        order.descending,
                        order.nulls_first,
                    )),
                    Some(TypedColumn::Boolean { .. }) => Some(stable_nullable_positions(
                        &resident.boolean_values(binding_rows, order.property, cancellation)?,
                        order.descending,
                        order.nulls_first,
                    )),
                    Some(TypedColumn::String { .. }) => Some(stable_nullable_positions(
                        &resident.string_values(binding_rows, order.property, cancellation)?,
                        order.descending,
                        order.nulls_first,
                    )),
                    Some(TypedColumn::Float { .. }) => Some(stable_nullable_positions(
                        &resident.float_values(binding_rows, order.property, cancellation)?,
                        order.descending,
                        order.nulls_first,
                    )),
                    _ => None,
                }
            } else {
                None
            };
            let positions = if let Some(positions) = cold_positions {
                positions
            } else {
                // Sparse deltas can introduce a property after the cold image was admitted or
                // remove it from an existing row. Read the current selected rows, not the cold
                // image's column schema, and never resurrect a removed value from that image.
                let values = binding_rows
                    .iter()
                    .enumerate()
                    .map(|(position, row)| {
                        if position & 4095 == 0 {
                            ensure_not_cancelled(cancellation)?;
                        }
                        match resident.property_value(*row, order.property)? {
                            None => Ok(None),
                            Some(ScalarValue::Boolean(value)) => {
                                Ok(Some(CpuSortValue::Boolean(value)))
                            }
                            Some(ScalarValue::Integer(value)) => {
                                Ok(Some(CpuSortValue::Integer(value)))
                            }
                            Some(ScalarValue::Float(value)) => Ok(Some(CpuSortValue::Float(value))),
                            Some(ScalarValue::String(value)) => {
                                Ok(Some(CpuSortValue::String(value)))
                            }
                            Some(_) => Err(Error::new(
                                ErrorCode::QueryType,
                                "resident sort property has no supported scalar value",
                            )),
                        }
                    })
                    .collect::<Result<Vec<_>>>()?;
                if let Some(first) = values.iter().flatten().next()
                    && values
                        .iter()
                        .flatten()
                        .any(|value| std::mem::discriminant(value) != std::mem::discriminant(first))
                {
                    return Err(Error::new(
                        ErrorCode::QueryType,
                        "resident sort property is not homogeneous",
                    ));
                }
                stable_nullable_positions(&values, order.descending, order.nulls_first)
            };
            select_pipeline_rows(&mut node_rows, &mut relationship_rows, &positions)?;
            if request.value_matrix.is_some() {
                select_value_matrix_indices(
                    &mut value_left_indices,
                    &mut value_right_indices,
                    &positions,
                )?;
            }
        }
        let has_mutation_continuation = request
            .mutation
            .as_ref()
            .is_some_and(|program| program.continuation.is_some());
        let post_offset = if has_mutation_continuation {
            0
        } else {
            request.offset
        };
        let post_limit = if has_mutation_continuation {
            usize::MAX
        } else {
            request.limit
        };
        let result_count = node_rows
            .first()
            .map_or(0, Vec::len)
            .saturating_sub(post_offset)
            .min(post_limit);
        if result_count > request.max_output_rows {
            return Err(Error::new(
                ErrorCode::ResultBudgetExceeded,
                "query row budget exceeded",
            ));
        }
        let selected = (post_offset..post_offset.saturating_add(result_count)).collect::<Vec<_>>();
        select_pipeline_rows(&mut node_rows, &mut relationship_rows, &selected)?;
        if request.value_matrix.is_some() {
            select_value_matrix_indices(
                &mut value_left_indices,
                &mut value_right_indices,
                &selected,
            )?;
        }
        ensure_not_cancelled(cancellation)?;
        let integer_columns = request
            .integer_projections
            .iter()
            .map(|projection| {
                let binding_rows = resident_pipeline_node_rows(&node_rows, projection.binding)?;
                let values =
                    resident.integer_values(binding_rows, projection.property, cancellation)?;
                Ok(ResidentI64Column {
                    binding: projection.binding,
                    property: projection.property,
                    values: values
                        .iter()
                        .map(|value| value.unwrap_or_default())
                        .collect(),
                    validity: values
                        .iter()
                        .map(|value| u8::from(value.is_some()))
                        .collect(),
                })
            })
            .collect::<Result<Vec<_>>>()?;
        let boolean_columns = request
            .property_null_projections
            .iter()
            .map(|projection| {
                let values = match projection.property {
                    Some(property) => resident
                        .integer_values(
                            resident_pipeline_node_rows(&node_rows, projection.binding)?,
                            property,
                            cancellation,
                        )?
                        .into_iter()
                        .map(|value| {
                            let is_null = value.is_none();
                            u8::from(if projection.negated {
                                !is_null
                            } else {
                                is_null
                            })
                        })
                        .collect(),
                    None => {
                        vec![u8::from(!projection.negated); node_rows.first().map_or(0, Vec::len)]
                    }
                };
                Ok(ResidentBooleanColumn {
                    projection: *projection,
                    values,
                })
            })
            .collect::<Result<Vec<_>>>()?;
        let start_rows = node_rows
            .first()
            .cloned()
            .ok_or_else(|| Error::internal("resident path omitted its start node column"))?;
        let end_rows = if expansion_count == 0 {
            Vec::new()
        } else {
            node_rows
                .pop()
                .ok_or_else(|| Error::internal("resident path omitted its final node column"))?
        };
        let intermediate_node_rows = if expansion_count == 0 {
            Vec::new()
        } else {
            node_rows.into_iter().skip(1).collect()
        };
        let edge_rows = relationship_rows.pop().unwrap_or_default();
        Ok(ResidentNodePipelineResult {
            start_rows,
            intermediate_node_rows,
            intermediate_edge_rows: relationship_rows,
            edge_rows,
            end_rows,
            integer_columns,
            boolean_columns,
            value_left_indices,
            value_right_indices,
            mutation,
        })
    }

    fn execute_delete_pipeline(
        &self,
        request: &ResidentDeleteRequest,
        cancellation: &CancellationToken,
    ) -> Result<ResidentDeleteResult> {
        ensure_not_cancelled(cancellation)?;
        request.validate()?;
        let resident = self
            .resident
            .get(&request.project)
            .ok_or_else(|| project_not_resident(request.project))?;
        if resident.bookmark != request.expected_bookmark
            || resident.graph_revision != request.expected_graph_revision
            || resident.layout_version != request.expected_layout_version
        {
            return Err(Error::new(
                ErrorCode::GpuAdmissionFailure,
                "resident DELETE command expected a different bookmark, graph revision, or layout version",
            ));
        }
        let _delete_scratch = self.governor.reserve_scratch(request.scratch_bytes()?)?;
        let expansion_count = request.selection.expansion_steps().count();
        let relationship_count = request.selection.relationship_column_count();
        let mut variable_path_read_dependencies = BTreeSet::new();
        let selected = if let Some(path_request) = &request.variable_path_selection {
            let path_result = self
                .execute_variable_path(path_request, cancellation)?
                .validate_for_publication(path_request, BackendKind::Cpu)?;
            if !matches!(
                path_result.final_relation(),
                super::ResidentVariablePathFinalRelation::Publications
            ) {
                return Err(Error::new(
                    ErrorCode::CorruptStorage,
                    "CPU variable-path DELETE selection returned a reduced relation",
                ));
            }
            let mut start_rows = Vec::with_capacity(path_result.rows().len());
            let mut end_rows = Vec::with_capacity(path_result.rows().len());
            for row in path_result.rows() {
                let path = row.path.as_ref().ok_or_else(|| {
                    Error::new(
                        ErrorCode::CorruptStorage,
                        "mandatory variable-path DELETE selection returned a null row",
                    )
                })?;
                let start = path.start().ok_or_else(|| {
                    Error::new(
                        ErrorCode::CorruptStorage,
                        "variable-path DELETE omitted its start",
                    )
                })?;
                let end = path.end().ok_or_else(|| {
                    Error::new(
                        ErrorCode::CorruptStorage,
                        "variable-path DELETE omitted its end",
                    )
                })?;
                start_rows.push(start);
                end_rows.push(end);
                variable_path_read_dependencies.extend(
                    path.nodes
                        .iter()
                        .copied()
                        .map(ResidentMutationReadDependency::Node),
                );
                variable_path_read_dependencies.extend(
                    path.relationships
                        .iter()
                        .copied()
                        .map(ResidentMutationReadDependency::Relationship),
                );
            }
            ResidentNodePipelineResult {
                start_rows,
                intermediate_node_rows: Vec::new(),
                intermediate_edge_rows: Vec::new(),
                edge_rows: vec![super::RESIDENT_NULL_ROW; path_result.rows().len()],
                end_rows,
                integer_columns: Vec::new(),
                boolean_columns: Vec::new(),
                value_left_indices: Vec::new(),
                value_right_indices: Vec::new(),
                mutation: None,
            }
        } else if request.selection_is_statically_empty {
            let mut proof_selection = request.selection.clone();
            proof_selection.initial_optional = false;
            let proof = self.execute_node_pipeline(&proof_selection, cancellation)?;
            if !proof.start_rows.is_empty()
                || proof
                    .intermediate_node_rows
                    .iter()
                    .chain(&proof.intermediate_edge_rows)
                    .any(|rows| !rows.is_empty())
                || !proof.edge_rows.is_empty()
                || !proof.end_rows.is_empty()
            {
                return Err(Error::new(
                    ErrorCode::GpuAdmissionFailure,
                    "CPU resident DELETE static-empty proof matched a fenced graph row",
                ));
            }
            ResidentNodePipelineResult {
                start_rows: vec![super::RESIDENT_NULL_ROW],
                intermediate_node_rows: (0..expansion_count.saturating_sub(1))
                    .map(|_| vec![super::RESIDENT_NULL_ROW])
                    .collect(),
                intermediate_edge_rows: (0..relationship_count.saturating_sub(1))
                    .map(|_| vec![super::RESIDENT_NULL_ROW])
                    .collect(),
                edge_rows: (relationship_count != 0)
                    .then(|| vec![super::RESIDENT_NULL_ROW])
                    .unwrap_or_default(),
                end_rows: (expansion_count != 0)
                    .then(|| vec![super::RESIDENT_NULL_ROW])
                    .unwrap_or_default(),
                integer_columns: Vec::new(),
                boolean_columns: Vec::new(),
                value_left_indices: Vec::new(),
                value_right_indices: Vec::new(),
                mutation: None,
            }
        } else {
            self.execute_node_pipeline(&request.selection, cancellation)?
        };
        let selector_rows = selected.start_rows.len();

        let mut nodes = Vec::with_capacity(expansion_count.saturating_add(1));
        nodes.push(selected.start_rows.clone());
        nodes.extend(selected.intermediate_node_rows.iter().cloned());
        if expansion_count != 0 {
            nodes.push(selected.end_rows.clone());
        }
        let mut relationships = Vec::with_capacity(relationship_count);
        relationships.extend(selected.intermediate_edge_rows.iter().cloned());
        if relationship_count != 0 {
            relationships.push(selected.edge_rows.clone());
        }
        if nodes.iter().any(|column| column.len() != selector_rows)
            || relationships
                .iter()
                .any(|column| column.len() != selector_rows)
        {
            return Err(Error::new(
                ErrorCode::CorruptStorage,
                "resident DELETE selection returned misaligned entity columns",
            ));
        }
        if request.selection_is_statically_empty
            && (selector_rows != 1
                || nodes
                    .iter()
                    .chain(&relationships)
                    .flatten()
                    .any(|row| *row != super::RESIDENT_NULL_ROW))
        {
            return Err(Error::new(
                ErrorCode::CorruptStorage,
                "CPU resident DELETE static-empty OPTIONAL proof selected a graph row",
            ));
        }

        let mut positions = (0..selector_rows).collect::<Vec<_>>();
        let mut selection_filter_cardinalities =
            Vec::with_capacity(request.selection_filters.len());
        for filter in &request.selection_filters {
            let input_rows = positions.len();
            let mut retained = Vec::with_capacity(input_rows);
            for (offset, position) in positions.into_iter().enumerate() {
                if offset & 4095 == 0 {
                    ensure_not_cancelled(cancellation)?;
                }
                let dense =
                    resident_pipeline_entity_row(&nodes, &relationships, filter.binding, position)?;
                let keep = match filter.property {
                    Some(property) => {
                        match resident.mutation_property_value(filter.binding, dense, property)? {
                            ScalarValue::Integer(value) => {
                                compare_i64(value, filter.operation, filter.operand)
                            }
                            _ => false,
                        }
                    }
                    None => false,
                };
                if keep {
                    retained.push(position);
                }
            }
            selection_filter_cardinalities.push((input_rows, retained.len()));
            positions = retained;
        }
        if !request.selection_filters.is_empty() {
            for column in &mut nodes {
                *column = positions.iter().map(|position| column[*position]).collect();
            }
            for column in &mut relationships {
                *column = positions.iter().map(|position| column[*position]).collect();
            }
        }
        let selected_rows = positions.len();

        let mut read_dependencies = variable_path_read_dependencies;
        for dense in nodes.iter().flatten().copied() {
            if dense != super::RESIDENT_NULL_ROW {
                read_dependencies.insert(ResidentMutationReadDependency::Node(dense));
            }
        }
        for dense in relationships.iter().flatten().copied() {
            if dense != super::RESIDENT_NULL_ROW {
                read_dependencies.insert(ResidentMutationReadDependency::Relationship(dense));
            }
        }
        if read_dependencies.len() > request.maximum_read_dependencies {
            return Err(Error::new(
                ErrorCode::ResultBudgetExceeded,
                "resident DELETE read dependencies exceeded their admitted capacity",
            ));
        }

        #[derive(Clone, Copy)]
        struct PendingIntent {
            source_row: u32,
            command: u16,
            target_kind: EntityKind,
            target_id: u64,
            origin: ResidentDeleteIntentOrigin,
        }
        let key = |kind: EntityKind, id: u64| {
            (
                match kind {
                    EntityKind::Relationship => 0_u8,
                    EntityKind::Node => 1_u8,
                },
                id,
            )
        };
        let mut pending = BTreeMap::<(u8, u64), PendingIntent>::new();
        let mut command_attempts = vec![0_u64; request.commands.len()];
        let mut node_targets = BTreeMap::<u64, (u32, u32, u16)>::new();
        for position in 0..selected_rows {
            if position & 4095 == 0 {
                ensure_not_cancelled(cancellation)?;
            }
            for (command_index, command) in request.commands.iter().enumerate() {
                if !cpu_delete_target_selector_includes_position(command.selector, position) {
                    continue;
                }
                let dense =
                    resident_pipeline_entity_row(&nodes, &relationships, command.target, position)?;
                let Some((target_kind, target_id)) =
                    resident.mutation_target_id(command.target, dense)?
                else {
                    continue;
                };
                command_attempts[command_index] = command_attempts[command_index]
                    .checked_add(1)
                    .ok_or_else(|| {
                        Error::new(
                            ErrorCode::ResultBudgetExceeded,
                            "resident DELETE command attempt count overflow",
                        )
                    })?;
                let source_row = u32::try_from(position).map_err(|_| {
                    Error::new(
                        ErrorCode::ResultBudgetExceeded,
                        "resident DELETE source row exceeds u32",
                    )
                })?;
                let command_index = u16::try_from(command_index).map_err(|_| {
                    Error::new(
                        ErrorCode::ResultBudgetExceeded,
                        "resident DELETE command index exceeds u16",
                    )
                })?;
                pending
                    .entry(key(target_kind, target_id))
                    .or_insert(PendingIntent {
                        source_row,
                        command: command_index,
                        target_kind,
                        target_id,
                        origin: ResidentDeleteIntentOrigin::Explicit,
                    });
                if target_kind == EntityKind::Node {
                    node_targets
                        .entry(target_id)
                        .or_insert((dense, source_row, command_index));
                }
            }
        }

        let explicit_relationships = pending
            .values()
            .filter(|intent| {
                intent.target_kind == EntityKind::Relationship
                    && intent.origin == ResidentDeleteIntentOrigin::Explicit
            })
            .map(|intent| intent.target_id)
            .collect::<BTreeSet<_>>();
        for (node_id, (dense, source_row, command_index)) in node_targets {
            let command = request
                .commands
                .get(command_index as usize)
                .ok_or_else(|| Error::internal("resident DELETE node command disappeared"))?;
            let incident = resident.active_incident_delete_edges(dense)?;
            if !command.detach
                && incident
                    .iter()
                    .any(|(edge_id, _)| !explicit_relationships.contains(edge_id))
            {
                return Err(Error::new(
                    ErrorCode::QueryType,
                    "DeleteConnectedNode: node still has relationships",
                ));
            }
            if command.detach {
                for (edge_id, _) in incident {
                    pending
                        .entry(key(EntityKind::Relationship, edge_id))
                        .or_insert(PendingIntent {
                            source_row,
                            command: command_index,
                            target_kind: EntityKind::Relationship,
                            target_id: edge_id,
                            origin: ResidentDeleteIntentOrigin::DetachIncident,
                        });
                }
            }
            let _ = node_id;
        }
        if pending.len() > request.maximum_delete_intents {
            return Err(Error::new(
                ErrorCode::ResultBudgetExceeded,
                "resident DELETE intents exceeded their admitted capacity",
            ));
        }
        let intents = pending
            .into_values()
            .map(|intent| ResidentDeleteIntent {
                source_row: intent.source_row,
                command: intent.command,
                target_kind: intent.target_kind,
                target_id: intent.target_id,
                origin: intent.origin,
            })
            .collect::<Vec<_>>();

        let cardinality = |value: usize| {
            u64::try_from(value).map_err(|_| {
                Error::new(
                    ErrorCode::ResultBudgetExceeded,
                    "resident DELETE cardinality exceeds u64",
                )
            })
        };
        let selected_cardinality = cardinality(selected_rows)?;
        let selector_cardinality = cardinality(selector_rows)?;
        let mut receipts = Vec::with_capacity(
            2_usize
                .saturating_add(request.selection_filters.len())
                .saturating_add(request.commands.len().saturating_mul(2))
                .saturating_add(
                    request
                        .continuation
                        .as_ref()
                        .map_or(0, |continuation| continuation.stages.len() + 1),
                ),
        );
        receipts.push(ResidentExecutionReceipt {
            execution: request.execution,
            obligation: request.selection_obligation,
            input_cardinality: selector_cardinality,
            output_cardinality: selector_cardinality,
            completion: ResidentDeviceCompletion::CpuReference,
        });
        for (filter, (input_rows, output_rows)) in request
            .selection_filters
            .iter()
            .zip(selection_filter_cardinalities)
        {
            receipts.push(ResidentExecutionReceipt {
                execution: request.execution,
                obligation: filter.obligation,
                input_cardinality: cardinality(input_rows)?,
                output_cardinality: cardinality(output_rows)?,
                completion: ResidentDeviceCompletion::CpuReference,
            });
        }
        let read_count = cardinality(read_dependencies.len())?;
        receipts.push(ResidentExecutionReceipt {
            execution: request.execution,
            obligation: request.read_dependency_obligation,
            input_cardinality: read_count,
            output_cardinality: read_count,
            completion: ResidentDeviceCompletion::CpuReference,
        });
        let mut effects = vec![0_u64; request.commands.len()];
        for intent in &intents {
            effects[intent.command as usize] = effects[intent.command as usize]
                .checked_add(1)
                .ok_or_else(|| {
                    Error::new(
                        ErrorCode::ResultBudgetExceeded,
                        "resident DELETE effect cardinality overflow",
                    )
                })?;
        }
        for (index, command) in request.commands.iter().enumerate() {
            receipts.push(ResidentExecutionReceipt {
                execution: request.execution,
                obligation: command.rhs_obligation,
                input_cardinality: selected_cardinality,
                output_cardinality: command_attempts[index],
                completion: ResidentDeviceCompletion::CpuReference,
            });
            receipts.push(ResidentExecutionReceipt {
                execution: request.execution,
                obligation: command.effect_obligation,
                input_cardinality: command_attempts[index],
                output_cardinality: effects[index],
                completion: ResidentDeviceCompletion::CpuReference,
            });
        }
        let final_relation = request
            .continuation
            .as_ref()
            .map(|continuation| {
                execute_cpu_delete_continuation(
                    resident,
                    request,
                    continuation,
                    &nodes,
                    &relationships,
                    selected_rows,
                    cancellation,
                )
            })
            .transpose()?;
        let final_relation = final_relation.map(|(relation, continuation_receipts)| {
            receipts.extend(continuation_receipts);
            relation
        });
        ensure_not_cancelled(cancellation)?;
        ResidentDeleteResult::completed(
            request,
            ResidentDeviceCompletion::CpuReference,
            selected_cardinality,
            command_attempts,
            intents,
            read_dependencies.into_iter().collect(),
            receipts,
            final_relation,
        )
    }

    fn execute_row_program(
        &self,
        request: &ResidentRowProgramRequest,
        cancellation: &CancellationToken,
    ) -> Result<ResidentRowProgramResult> {
        ensure_not_cancelled(cancellation)?;
        request.validate()?;
        let resident = self
            .resident
            .get(&request.project)
            .ok_or_else(|| project_not_resident(request.project))?;
        if resident.bookmark != request.expected_bookmark
            || resident.graph_revision != request.expected_graph_revision
            || resident.layout_version != request.expected_layout_version
        {
            return Err(Error::new(
                ErrorCode::GpuAdmissionFailure,
                "resident typed-row program expected a different bookmark, graph revision, or layout version",
            ));
        }

        let scalar_rows = request.scalar_input_rows()?;
        let input = if scalar_rows.is_some() {
            ResidentNodePipelineResult {
                start_rows: Vec::new(),
                intermediate_node_rows: Vec::new(),
                intermediate_edge_rows: Vec::new(),
                edge_rows: Vec::new(),
                end_rows: Vec::new(),
                integer_columns: Vec::new(),
                boolean_columns: Vec::new(),
                value_left_indices: Vec::new(),
                value_right_indices: Vec::new(),
                mutation: None,
            }
        } else {
            self.execute_node_pipeline(&request.input, cancellation)?
        };
        let input_rows = scalar_rows.unwrap_or_else(|| input.start_rows.len());
        let scratch_bytes = request.scratch_bytes(input_rows)?;
        let _scratch = self.governor.reserve_scratch(scratch_bytes)?;
        let mut loader = |binding,
                          property,
                          value_type,
                          maximum_variable_bytes,
                          duration_accessor,
                          rows: &[u32],
                          cancellation: &CancellationToken| {
            if let Some(accessor) = duration_accessor {
                resident.row_program_duration_accessor_values(
                    binding,
                    property,
                    accessor,
                    rows,
                    cancellation,
                )
            } else {
                resident.row_program_property_values(
                    binding,
                    property,
                    value_type,
                    maximum_variable_bytes,
                    rows,
                    cancellation,
                )
            }
        };
        execute_reference_row_program(request, input, scratch_bytes, &mut loader, cancellation)
    }

