    fn execute_nullable_relation(
        &self,
        request: &ResidentNullableRelationRequest,
        cancellation: &CancellationToken,
    ) -> Result<ResidentNullableRelationResult> {
        ensure_not_cancelled(cancellation)?;
        request.validate()?;
        let resident = self
            .resident
            .get(&request.generation.project)
            .ok_or_else(|| project_not_resident(request.generation.project))?;
        if resident.bookmark != request.generation.bookmark
            || resident.graph_revision != request.generation.graph_revision
            || resident.layout_version != request.generation.layout_version
            || resident.node_capacity != request.capacities.node_slot_count as usize
            || resident.edge_capacity != request.capacities.relationship_slot_count as usize
        {
            return Err(Error::new(
                ErrorCode::GpuAdmissionFailure,
                "resident nullable relation expected a different bookmark, graph revision, layout, or dense-row generation",
            ));
        }

        let mut visible_nodes = 0_usize;
        for row in 0..resident.node_capacity {
            if row.is_multiple_of(4096) {
                ensure_not_cancelled(cancellation)?;
            }
            if resident.node_is_visible(row as u32, &[], request.program.layers) {
                visible_nodes = visible_nodes.checked_add(1).ok_or_else(|| {
                    Error::new(
                        ErrorCode::ResultBudgetExceeded,
                        "CPU nullable visible-node count overflow",
                    )
                })?;
            }
        }
        let mut visible_relationships = 0_usize;
        for row in 0..resident.edge_capacity {
            if row.is_multiple_of(4096) {
                ensure_not_cancelled(cancellation)?;
            }
            if resident.edge_is_visible(row as u32, &[], request.program.layers) {
                visible_relationships = visible_relationships.checked_add(1).ok_or_else(|| {
                    Error::new(
                        ErrorCode::ResultBudgetExceeded,
                        "CPU nullable visible-relationship count overflow",
                    )
                })?;
            }
        }
        if visible_nodes != request.capacities.visible_node_rows as usize
            || visible_relationships != request.capacities.visible_relationship_rows as usize
        {
            return Err(Error::new(
                ErrorCode::GpuAdmissionFailure,
                "resident nullable relation visible-row capacities do not match the pinned generation",
            ));
        }

        let scratch_bytes = request.scratch_bytes()?;
        let _scratch = self.governor.reserve_scratch(scratch_bytes)?;
        execute_cpu_nullable_relation(resident, request, cancellation)
    }

    fn execute_pattern_predicate(
        &self,
        request: &ResidentPatternPredicateRequest,
        cancellation: &CancellationToken,
    ) -> Result<ResidentPatternPredicateResult> {
        ensure_not_cancelled(cancellation)?;
        request.validate()?;
        let resident = self
            .resident
            .get(&request.project)
            .ok_or_else(|| project_not_resident(request.project))?;
        if resident.bookmark != request.expected_bookmark
            || resident.graph_revision != request.expected_graph_revision
            || resident.layout_version != request.expected_layout_version
        {
            return Err(Error::new(
                ErrorCode::GpuAdmissionFailure,
                "resident pattern predicate expected a different bookmark, graph revision, or layout version",
            ));
        }
        match &request.input {
            ResidentPatternPredicateInput::Rows(rows) => {
                if rows
                    .iter()
                    .any(|row| *row as usize >= resident.node_capacity)
                {
                    return Err(Error::new(
                        ErrorCode::QueryType,
                        "resident pattern predicate outer row is out of bounds",
                    ));
                }
            }
            ResidentPatternPredicateInput::VisibleNodeScan { node_slots, .. } => {
                if *node_slots != resident.node_capacity {
                    return Err(Error::new(
                        ErrorCode::GpuAdmissionFailure,
                        "resident pattern scan node-slot count does not match the resident image",
                    ));
                }
            }
        }
        cpu_pattern_validate_property_columns(resident, &request.program.leaves, cancellation)?;
        let _scratch = self.governor.reserve_scratch(request.scratch_bytes()?)?;
        let row_count = request.input.row_count();
        let mut leaf_masks = Vec::with_capacity(request.program.leaves.len());
        let mut receipts = Vec::with_capacity(request.obligations().count());
        let visible_input_cardinality = match &request.input {
            ResidentPatternPredicateInput::Rows(rows) => rows.len() as u64,
            ResidentPatternPredicateInput::VisibleNodeScan {
                node_slots,
                obligation,
            } => {
                let mut visible = 0_u64;
                for row in 0..*node_slots {
                    if row.is_multiple_of(4096) {
                        ensure_not_cancelled(cancellation)?;
                    }
                    let source = u32::try_from(row).map_err(|_| {
                        Error::new(
                            ErrorCode::ResultBudgetExceeded,
                            "resident pattern scan row exceeds u32",
                        )
                    })?;
                    visible = visible
                        .checked_add(u64::from(resident.node_is_visible(
                            source,
                            &[],
                            request.layers,
                        )))
                        .ok_or_else(|| Error::internal("CPU pattern scan count overflow"))?;
                }
                receipts.push(ResidentExecutionReceipt {
                    execution: request.program.execution,
                    obligation: *obligation,
                    input_cardinality: *node_slots as u64,
                    output_cardinality: visible,
                    completion: ResidentDeviceCompletion::CpuReference,
                });
                visible
            }
        };
        for (leaf_index, leaf) in request.program.leaves.iter().enumerate() {
            let mut mask = Vec::with_capacity(row_count);
            let mut witness_count = 0_u64;
            for row_index in 0..row_count {
                if row_index.is_multiple_of(4096) {
                    ensure_not_cancelled(cancellation)?;
                }
                let source = match &request.input {
                    ResidentPatternPredicateInput::Rows(rows) => rows[row_index],
                    ResidentPatternPredicateInput::VisibleNodeScan { .. } => {
                        u32::try_from(row_index).map_err(|_| {
                            Error::new(
                                ErrorCode::ResultBudgetExceeded,
                                "resident pattern scan row exceeds u32",
                            )
                        })?
                    }
                };
                let witness = if request.input.is_fused_visible_node_scan()
                    && !resident.node_is_visible(source, &[], request.layers)
                {
                    false
                } else {
                    cpu_pattern_leaf_witness(resident, source, leaf, request.layers, cancellation)?
                };
                witness_count = witness_count
                    .checked_add(u64::from(witness))
                    .ok_or_else(|| Error::internal("CPU pattern witness count overflow"))?;
                mask.push(witness);
            }
            leaf_masks.push(mask);
            receipts.push(ResidentExecutionReceipt {
                execution: request.program.execution,
                obligation: leaf.obligation,
                input_cardinality: visible_input_cardinality,
                output_cardinality: witness_count,
                completion: ResidentDeviceCompletion::CpuReference,
            });
            debug_assert!(matches!(
                leaf.obligation.scope,
                ResidentObligationScope::PatternLeaf(index)
                    if usize::from(index) == leaf_index
            ));
        }

        let mut output_rows = Vec::with_capacity(request.max_output_rows.min(row_count));
        for row_index in 0..row_count {
            if row_index.is_multiple_of(4096) {
                ensure_not_cancelled(cancellation)?;
            }
            let row = match &request.input {
                ResidentPatternPredicateInput::Rows(rows) => rows[row_index],
                ResidentPatternPredicateInput::VisibleNodeScan { .. } => u32::try_from(row_index)
                    .map_err(|_| {
                    Error::new(
                        ErrorCode::ResultBudgetExceeded,
                        "resident pattern scan row exceeds u32",
                    )
                })?,
            };
            if request.input.is_fused_visible_node_scan()
                && !resident.node_is_visible(row, &[], request.layers)
            {
                continue;
            }
            if cpu_pattern_boolean_value(&request.program.instructions, &leaf_masks, row_index)? {
                if output_rows.len() == request.max_output_rows {
                    return Err(Error::new(
                        ErrorCode::ResultBudgetExceeded,
                        "resident pattern predicate exceeded its output row budget",
                    ));
                }
                output_rows.push(row);
            }
        }
        receipts.push(ResidentExecutionReceipt {
            execution: request.program.execution,
            obligation: request.program.final_obligation,
            input_cardinality: visible_input_cardinality,
            output_cardinality: output_rows.len() as u64,
            completion: ResidentDeviceCompletion::CpuReference,
        });
        ensure_not_cancelled(cancellation)?;
        Ok(ResidentPatternPredicateResult::completed(
            request.program.execution,
            resident.bookmark,
            resident.graph_revision,
            resident.layout_version,
            output_rows,
            receipts,
        ))
    }

    fn execute_pattern_count(
        &self,
        request: &ResidentPatternCountRequest,
        cancellation: &CancellationToken,
    ) -> Result<ResidentPatternCountResult> {
        ensure_not_cancelled(cancellation)?;
        request.validate()?;
        let resident = self
            .resident
            .get(&request.project)
            .ok_or_else(|| project_not_resident(request.project))?;
        if resident.bookmark != request.expected_bookmark
            || resident.graph_revision != request.expected_graph_revision
            || resident.layout_version != request.expected_layout_version
            || resident.node_capacity != request.node_slots
            || resident.edge_capacity != request.edge_slots
        {
            return Err(Error::new(
                ErrorCode::GpuAdmissionFailure,
                "resident pattern count expected a different bookmark, graph revision, layout, or dense-row generation",
            ));
        }
        let _scratch = self.governor.reserve_scratch(request.scratch_bytes()?)?;
        let labels = match &request.start_labels {
            ResidentPatternCountStartLabels::Known(labels) => Some(labels.as_slice()),
            ResidentPatternCountStartLabels::Never => None,
        };
        let mut node_rows = Vec::with_capacity(request.max_output_rows.min(request.node_slots));
        let mut counts = Vec::with_capacity(request.max_output_rows.min(request.node_slots));
        let mut traversal_cardinality = 0_u64;
        if let Some(labels) = labels {
            for row in 0..request.node_slots {
                if row.is_multiple_of(1024) {
                    ensure_not_cancelled(cancellation)?;
                }
                let row = u32::try_from(row).map_err(|_| {
                    Error::new(
                        ErrorCode::ResultBudgetExceeded,
                        "CPU resident pattern-count row exceeds u32",
                    )
                })?;
                if !resident.node_is_visible(row, labels, request.layers) {
                    continue;
                }
                if node_rows.len() == request.max_output_rows {
                    return Err(Error::new(
                        ErrorCode::ResultBudgetExceeded,
                        "resident pattern count exceeded its output row budget",
                    ));
                }
                let count = cpu_pattern_count_one_hop(resident, row, request, cancellation)?;
                traversal_cardinality = traversal_cardinality
                    .checked_add(u64::from(count))
                    .ok_or_else(|| Error::internal("CPU resident pattern-count total overflow"))?;
                node_rows.push(row);
                counts.push(count);
            }
        }
        let output_cardinality = node_rows.len() as u64;
        let completion = ResidentDeviceCompletion::CpuReference;
        let receipts = vec![
            ResidentExecutionReceipt {
                execution: request.execution,
                obligation: request.scan_obligation,
                input_cardinality: request.node_slots as u64,
                output_cardinality,
                completion,
            },
            ResidentExecutionReceipt {
                execution: request.execution,
                obligation: request.traversal_obligation,
                input_cardinality: output_cardinality,
                output_cardinality: traversal_cardinality,
                completion,
            },
            ResidentExecutionReceipt {
                execution: request.execution,
                obligation: request.final_obligation,
                input_cardinality: output_cardinality,
                output_cardinality,
                completion,
            },
        ];
        ensure_not_cancelled(cancellation)?;
        Ok(ResidentPatternCountResult::completed(
            request,
            resident.bookmark,
            resident.graph_revision,
            resident.layout_version,
            node_rows,
            counts,
            receipts,
        ))
    }

    fn execute_pattern_predicate_pairs(
        &self,
        request: &ResidentPatternPairPredicateRequest,
        cancellation: &CancellationToken,
    ) -> Result<ResidentPatternPairPredicateResult> {
        ensure_not_cancelled(cancellation)?;
        request.validate()?;
        let resident = self
            .resident
            .get(&request.project)
            .ok_or_else(|| project_not_resident(request.project))?;
        if resident.bookmark != request.expected_bookmark
            || resident.graph_revision != request.expected_graph_revision
            || resident.layout_version != request.expected_layout_version
        {
            return Err(Error::new(
                ErrorCode::GpuAdmissionFailure,
                "resident paired pattern expected a different bookmark, graph revision, or layout version",
            ));
        }
        if request.input.node_slots != resident.node_capacity {
            return Err(Error::new(
                ErrorCode::GpuAdmissionFailure,
                "resident paired pattern node-slot count does not match the resident image",
            ));
        }
        let _scratch = self.governor.reserve_scratch(request.scratch_bytes()?)?;
        let node_slots = request.input.node_slots;
        let node_slots_u64 = u64::try_from(node_slots).map_err(|_| {
            Error::new(
                ErrorCode::GpuAdmissionFailure,
                "CPU paired pattern node-slot cardinality exceeds u64",
            )
        })?;
        let pair_domain = request.logical_pair_domain()?;
        let pair_chunk_rows = u64::try_from(request.pair_chunk_rows()?).map_err(|_| {
            Error::new(
                ErrorCode::ResultBudgetExceeded,
                "CPU paired pattern chunk cardinality exceeds u64",
            )
        })?;

        let mut n_visible = Vec::with_capacity(node_slots);
        let mut n_visible_count = 0_u64;
        for row in 0..node_slots {
            if row.is_multiple_of(256) {
                ensure_not_cancelled(cancellation)?;
            }
            let visible = resident.node_is_visible(row as u32, &[], request.layers);
            n_visible.push(visible);
            n_visible_count = n_visible_count
                .checked_add(u64::from(visible))
                .ok_or_else(|| Error::internal("CPU paired n scan count overflow"))?;
        }
        let mut m_visible = Vec::with_capacity(node_slots);
        let mut m_visible_count = 0_u64;
        for row in 0..node_slots {
            if row.is_multiple_of(256) {
                ensure_not_cancelled(cancellation)?;
            }
            let visible = resident.node_is_visible(row as u32, &[], request.layers);
            m_visible.push(visible);
            m_visible_count = m_visible_count
                .checked_add(u64::from(visible))
                .ok_or_else(|| Error::internal("CPU paired m scan count overflow"))?;
        }
        let visible_pairs = n_visible_count
            .checked_mul(m_visible_count)
            .ok_or_else(|| Error::internal("CPU paired Cartesian count overflow"))?;

        let output_capacity = request
            .max_output_pairs
            .min(usize::try_from(pair_domain).unwrap_or(usize::MAX));
        let mut pair_positions = Vec::with_capacity(output_capacity);
        let mut n_rows = Vec::with_capacity(output_capacity);
        let mut m_rows = Vec::with_capacity(output_capacity);
        let mut pair_base = 0_u64;
        while pair_base < pair_domain {
            let dispatch_count = pair_domain.saturating_sub(pair_base).min(pair_chunk_rows);
            let pair_end = pair_base
                .checked_add(dispatch_count)
                .ok_or_else(|| Error::internal("CPU paired pattern chunk end overflow"))?;
            for position in pair_base..pair_end {
                if position.is_multiple_of(256) {
                    ensure_not_cancelled(cancellation)?;
                }
                let n = position / node_slots_u64;
                let m = position % node_slots_u64;
                let n_index = usize::try_from(n)
                    .map_err(|_| Error::internal("CPU paired n row exceeds host addressing"))?;
                let m_index = usize::try_from(m)
                    .map_err(|_| Error::internal("CPU paired m row exceeds host addressing"))?;
                if !n_visible[n_index] || !m_visible[m_index] {
                    continue;
                }
                let n_row = u32::try_from(n)
                    .map_err(|_| Error::internal("CPU paired n row exceeds graph locator width"))?;
                let m_row = u32::try_from(m)
                    .map_err(|_| Error::internal("CPU paired m row exceeds graph locator width"))?;
                if cpu_pattern_pair_leaf_matches(
                    resident,
                    n_row,
                    m_row,
                    &request.program.leaf,
                    request.layers,
                    cancellation,
                )? {
                    if pair_positions.len() == request.max_output_pairs {
                        return Err(Error::new(
                            ErrorCode::ResultBudgetExceeded,
                            "resident paired pattern exceeded its output pair budget",
                        ));
                    }
                    pair_positions.push(position);
                    n_rows.push(n_row);
                    m_rows.push(m_row);
                }
            }
            pair_base = pair_end;
        }
        let matched = u64::try_from(pair_positions.len())
            .map_err(|_| Error::internal("CPU paired output cardinality exceeds u64"))?;
        let completion = ResidentDeviceCompletion::CpuReference;
        let execution = request.program.execution;
        let receipts = vec![
            ResidentExecutionReceipt {
                execution,
                obligation: request.input.n_obligation,
                input_cardinality: node_slots_u64,
                output_cardinality: n_visible_count,
                completion,
            },
            ResidentExecutionReceipt {
                execution,
                obligation: request.input.m_obligation,
                input_cardinality: node_slots_u64,
                output_cardinality: m_visible_count,
                completion,
            },
            ResidentExecutionReceipt {
                execution,
                obligation: request.input.cartesian_obligation,
                input_cardinality: visible_pairs,
                output_cardinality: visible_pairs,
                completion,
            },
            ResidentExecutionReceipt {
                execution,
                obligation: request.program.leaf.obligation,
                input_cardinality: visible_pairs,
                output_cardinality: matched,
                completion,
            },
            ResidentExecutionReceipt {
                execution,
                obligation: request.program.final_obligation,
                input_cardinality: visible_pairs,
                output_cardinality: matched,
                completion,
            },
        ];
        ensure_not_cancelled(cancellation)?;
        Ok(ResidentPatternPairPredicateResult::completed(
            execution,
            resident.bookmark,
            resident.graph_revision,
            resident.layout_version,
            pair_positions,
            n_rows,
            m_rows,
            receipts,
        ))
    }

