    fn supports_native_to_boolean(&self) -> bool {
        true
    }

    fn execute_to_boolean(
        &self,
        request: &ResidentToBooleanRequest,
        cancellation: &CancellationToken,
    ) -> Result<ResidentToBooleanResult> {
        ensure_not_cancelled(cancellation)?;
        let _scratch = self.governor.reserve_scratch(
            request
                .inputs
                .iter()
                .map(|input| match input {
                    ResidentScalarInput::String(value) => value.len().saturating_add(3),
                    ResidentScalarInput::Null
                    | ResidentScalarInput::Boolean(_)
                    | ResidentScalarInput::Other => 3,
                })
                .sum(),
        )?;
        let values = request
            .inputs
            .iter()
            .enumerate()
            .map(|(row, input)| {
                if row & 4095 == 0 {
                    ensure_not_cancelled(cancellation)?;
                }
                Ok(match input {
                    ResidentScalarInput::Null => ResidentBooleanValue::Null,
                    ResidentScalarInput::Boolean(value) => ResidentBooleanValue::Boolean(*value),
                    ResidentScalarInput::String(value) if value.eq_ignore_ascii_case("true") => {
                        ResidentBooleanValue::Boolean(true)
                    }
                    ResidentScalarInput::String(value) if value.eq_ignore_ascii_case("false") => {
                        ResidentBooleanValue::Boolean(false)
                    }
                    ResidentScalarInput::String(_) => ResidentBooleanValue::Null,
                    ResidentScalarInput::Other => ResidentBooleanValue::InvalidArgument,
                })
            })
            .collect::<Result<Vec<_>>>()?;
        ensure_not_cancelled(cancellation)?;
        Ok(ResidentToBooleanResult { values })
    }

    fn execute_row_mutation(
        &self,
        request: &ResidentRowMutationRequest,
        cancellation: &CancellationToken,
    ) -> Result<ResidentRowMutationResult> {
        request.validate()?;
        ensure_not_cancelled(cancellation)?;
        let resident = self
            .resident
            .get(&request.generation.project)
            .ok_or_else(|| project_not_resident(request.generation.project))?;
        if resident.bookmark != request.generation.bookmark
            || resident.graph_revision != request.generation.graph_revision
            || resident.layout_version != request.generation.layout_version
        {
            return Err(Error::new(
                ErrorCode::GpuAdmissionFailure,
                "CPU row mutation targets a stale resident graph generation",
            ));
        }
        let _create_scratch = if let Some(body) = request.create_body() {
            let resident_node_slots = u64::try_from(resident.node_capacity).map_err(|_| {
                Error::new(
                    ErrorCode::GpuAdmissionFailure,
                    "CPU resident node-slot domain exceeds u64",
                )
            })?;
            if body.capacities.resident_node_slots != resident_node_slots {
                return Err(Error::new(
                    ErrorCode::GpuAdmissionFailure,
                    "CPU row CREATE targets a stale resident node-slot domain",
                ));
            }
            Some(
                self.governor
                    .reserve_scratch(request.create_scratch_bytes()?)?,
            )
        } else if let Some(body) = request.bound_relationship_merge_body() {
            let resident_node_slots = u64::try_from(resident.node_capacity).map_err(|_| {
                Error::new(
                    ErrorCode::GpuAdmissionFailure,
                    "CPU resident node-slot domain exceeds u64",
                )
            })?;
            let resident_relationship_slots =
                u64::try_from(resident.edge_capacity).map_err(|_| {
                    Error::new(
                        ErrorCode::GpuAdmissionFailure,
                        "CPU resident relationship-slot domain exceeds u64",
                    )
                })?;
            if body.capacities.resident_node_slots != resident_node_slots
                || body.capacities.resident_relationship_slots != resident_relationship_slots
            {
                return Err(Error::new(
                    ErrorCode::GpuAdmissionFailure,
                    "CPU bound relationship MERGE targets a stale resident slot domain",
                ));
            }
            Some(self.governor.reserve_scratch(
                usize::try_from(body.capacities.scratch_bytes).map_err(|_| {
                    Error::new(
                        ErrorCode::GpuAdmissionFailure,
                        "CPU bound relationship scratch exceeds host address space",
                    )
                })?,
            )?)
        } else {
            None
        };
        execute_cpu_row_mutation(resident, request, cancellation)
    }

