    fn execute_procedure_table(
        &self,
        request: &ResidentProcedureTableRequest,
        cancellation: &CancellationToken,
    ) -> Result<ResidentProcedureTableResult> {
        request.validate()?;
        let _scratch = self.governor.reserve_scratch(request.scratch_bytes()?)?;
        ensure_not_cancelled(cancellation)?;
        let selected_source_rows = request
            .table()
            .matching_rows_reference(request.arguments().to_vec())?;
        ensure_not_cancelled(cancellation)?;
        if selected_source_rows.len() > request.maximum_output_rows() as usize {
            return Err(Error::new(
                ErrorCode::ResultBudgetExceeded,
                "procedure-table selection exceeded its admitted output row capacity",
            ));
        }
        let output_cardinality = u64::try_from(selected_source_rows.len()).map_err(|_| {
            Error::new(
                ErrorCode::ResultBudgetExceeded,
                "procedure-table CPU output cardinality exceeds u64",
            )
        })?;
        let receipt = ResidentExecutionReceipt {
            execution: request.execution(),
            obligation: request.obligation(),
            input_cardinality: u64::from(request.table().row_count()),
            output_cardinality,
            completion: ResidentDeviceCompletion::CpuReference,
        };
        ResidentProcedureTableResult::completed(
            request,
            selected_source_rows,
            ResidentDeviceCompletion::CpuReference,
            vec![receipt],
        )
    }

