    #[test]
    fn sealed_graph_scalar_comparison_uses_numeric_and_three_valued_semantics() -> Result<()> {
        let row = CpuSegmentedProgramRow::new();
        for (expression, expected) in [
            (
                binary(
                    ResidentQuantifierValue::Integer(1),
                    ResidentQuantifierBinary::Equal,
                    ResidentQuantifierValue::Float(1.0_f64.to_bits()),
                ),
                CpuSegmentedProgramValue::Boolean(true),
            ),
            (
                binary(
                    ResidentQuantifierValue::String("a".to_owned()),
                    ResidentQuantifierBinary::NotEqual,
                    ResidentQuantifierValue::String("b".to_owned()),
                ),
                CpuSegmentedProgramValue::Boolean(true),
            ),
            (
                binary(
                    ResidentQuantifierValue::Integer(1),
                    ResidentQuantifierBinary::Less,
                    ResidentQuantifierValue::Integer(2),
                ),
                CpuSegmentedProgramValue::Boolean(true),
            ),
            (
                binary(
                    ResidentQuantifierValue::Integer(1),
                    ResidentQuantifierBinary::LessOrEqual,
                    ResidentQuantifierValue::Integer(1),
                ),
                CpuSegmentedProgramValue::Boolean(true),
            ),
            (
                binary(
                    ResidentQuantifierValue::Integer(2),
                    ResidentQuantifierBinary::Greater,
                    ResidentQuantifierValue::Integer(1),
                ),
                CpuSegmentedProgramValue::Boolean(true),
            ),
            (
                binary(
                    ResidentQuantifierValue::Integer(2),
                    ResidentQuantifierBinary::GreaterOrEqual,
                    ResidentQuantifierValue::Integer(2),
                ),
                CpuSegmentedProgramValue::Boolean(true),
            ),
            (
                binary(
                    ResidentQuantifierValue::Null,
                    ResidentQuantifierBinary::Greater,
                    ResidentQuantifierValue::Integer(0),
                ),
                CpuSegmentedProgramValue::Null,
            ),
        ] {
            assert_eq!(
                cpu_segmented_program_expression(&expression, &row, 0)?,
                expected
            );
        }
        Ok(())
    }

    #[test]
    fn sealed_graph_documents_evaluate_and_form_canonical_distinct_keys() -> Result<()> {
        let expression = ResidentQuantifierExpression::Map(vec![(
            "name".to_owned(),
            ResidentQuantifierExpression::List(vec![
                ResidentQuantifierExpression::Literal(ResidentQuantifierValue::Integer(1)),
                ResidentQuantifierExpression::Map(vec![(
                    "nested".to_owned(),
                    ResidentQuantifierExpression::Literal(ResidentQuantifierValue::String(
                        "value".to_owned(),
                    )),
                )]),
            ]),
        )]);
        let value =
            cpu_segmented_program_expression(&expression, &CpuSegmentedProgramRow::new(), 2)?;
        assert_eq!(
            value,
            CpuSegmentedProgramValue::Map(vec![(
                "name".to_owned(),
                CpuSegmentedProgramValue::List(vec![
                    CpuSegmentedProgramValue::Integer(1),
                    CpuSegmentedProgramValue::Map(vec![(
                        "nested".to_owned(),
                        CpuSegmentedProgramValue::String("value".to_owned()),
                    )]),
                ]),
            )])
        );

        let numerically_equal = CpuSegmentedProgramValue::Map(vec![(
            "name".to_owned(),
            CpuSegmentedProgramValue::List(vec![
                CpuSegmentedProgramValue::Float(1.0_f64.to_bits()),
                CpuSegmentedProgramValue::Map(vec![(
                    "nested".to_owned(),
                    CpuSegmentedProgramValue::String("value".to_owned()),
                )]),
            ]),
        )]);
        assert_eq!(
            cpu_segmented_program_key(&value),
            cpu_segmented_program_key(&numerically_equal),
            "DISTINCT must use recursive Cypher numeric equality inside maps and lists"
        );

        let expected_document = DocumentMap::new(BTreeMap::from([(
            Arc::<str>::from("name"),
            DocumentItem::List(vec![
                DocumentItem::Scalar(ScalarValue::Integer(1)),
                DocumentItem::Map(BTreeMap::from([(
                    Arc::<str>::from("nested"),
                    DocumentItem::Scalar(ScalarValue::String(Arc::from("value"))),
                )])),
            ]),
        )]))?;
        let mut arena = Vec::new();
        let cell = cpu_segmented_program_scalar_cell(
            &value,
            &mut arena,
            expected_document.as_bytes().len(),
        )?;
        assert_eq!(cell.tag, ResidentSegmentedValueTag::Map);
        assert_eq!(cell.payload, 0);
        assert_eq!(cell.auxiliary, expected_document.as_bytes().len() as u64);
        assert_eq!(arena, expected_document.as_bytes());
        Ok(())
    }

