#[cfg(test)]
mod temporal_value_comparison_cpu_tests {
    use super::*;
    use crate::{
        ResidentTemporalValueFunction, ResidentTemporalValueInvocation,
        ResidentTemporalValueProgramRequest,
    };

    fn invocation(
        function: ResidentTemporalValueFunction,
        input: ResidentTemporalValueInput,
    ) -> ResidentTemporalValueInvocation {
        ResidentTemporalValueInvocation { function, input }
    }

    fn text(
        function: ResidentTemporalValueFunction,
        value: &str,
    ) -> ResidentTemporalValueInvocation {
        invocation(
            function,
            ResidentTemporalValueInput::String(value.to_owned()),
        )
    }

    fn comparison(
        function: ResidentTemporalValueFunction,
        operation: CompareOp,
        left: u16,
        right: u16,
    ) -> ResidentTemporalValueInvocation {
        invocation(
            function,
            ResidentTemporalValueInput::Comparison {
                operation,
                left,
                right,
            },
        )
    }

    fn execute(
        invocations: Vec<ResidentTemporalValueInvocation>,
        output_registers: Vec<u16>,
    ) -> Result<Vec<ResidentTemporalValue>> {
        let backend = CpuBackend::new(1024 * 1024, 0);
        backend
            .execute_temporal_value_program(
                &ResidentTemporalValueProgramRequest {
                    invocations,
                    output_registers,
                },
                &CancellationToken::new(),
            )
            .map(|result| result.values)
    }

    #[test]
    fn all_six_comparison_operators_execute_as_boolean_registers() -> Result<()> {
        let mut invocations = vec![
            text(ResidentTemporalValueFunction::Date, "1970-01-01"),
            text(ResidentTemporalValueFunction::Date, "1970-01-02"),
        ];
        for operation in [
            CompareOp::Eq,
            CompareOp::NotEq,
            CompareOp::Less,
            CompareOp::LessOrEqual,
            CompareOp::Greater,
            CompareOp::GreaterOrEqual,
        ] {
            invocations.push(comparison(
                ResidentTemporalValueFunction::Date,
                operation,
                0,
                1,
            ));
        }
        let values = execute(invocations, (2_u16..8).collect())?;
        assert_eq!(
            values,
            [
                ResidentTemporalValue::Boolean(false),
                ResidentTemporalValue::Boolean(true),
                ResidentTemporalValue::Boolean(true),
                ResidentTemporalValue::Boolean(true),
                ResidentTemporalValue::Boolean(false),
                ResidentTemporalValue::Boolean(false),
            ]
        );
        Ok(())
    }

    #[test]
    fn null_cross_family_and_invalid_argument_semantics_are_exact() -> Result<()> {
        let values = execute(
            vec![
                invocation(
                    ResidentTemporalValueFunction::Date,
                    ResidentTemporalValueInput::Null,
                ),
                text(ResidentTemporalValueFunction::Date, "1970-01-01"),
                comparison(ResidentTemporalValueFunction::Date, CompareOp::Eq, 0, 1),
                comparison(ResidentTemporalValueFunction::Date, CompareOp::Less, 0, 1),
                text(
                    ResidentTemporalValueFunction::LocalDateTime,
                    "1970-01-01T00:00:00",
                ),
                comparison(ResidentTemporalValueFunction::Date, CompareOp::Eq, 1, 4),
                comparison(ResidentTemporalValueFunction::Date, CompareOp::NotEq, 1, 4),
                comparison(ResidentTemporalValueFunction::Date, CompareOp::Less, 1, 4),
                invocation(
                    ResidentTemporalValueFunction::Date,
                    ResidentTemporalValueInput::Other,
                ),
                comparison(ResidentTemporalValueFunction::Date, CompareOp::Eq, 8, 0),
            ],
            vec![2, 3, 5, 6, 7, 9],
        )?;
        assert_eq!(
            values,
            [
                ResidentTemporalValue::Null,
                ResidentTemporalValue::Null,
                ResidentTemporalValue::Boolean(false),
                ResidentTemporalValue::Boolean(true),
                ResidentTemporalValue::Null,
                ResidentTemporalValue::InvalidArgument,
            ]
        );
        Ok(())
    }

    #[test]
    fn canonical_temporal_order_tuples_and_exact_equality_are_preserved() -> Result<()> {
        const HOUR: i64 = 3_600 * 1_000_000_000;
        let cases = [
            (
                ResidentTemporalValue::Date(-1),
                ResidentTemporalValue::Date(0),
                CompareOp::Less,
                ResidentTemporalValue::Boolean(true),
            ),
            (
                ResidentTemporalValue::LocalTime(2),
                ResidentTemporalValue::LocalTime(1),
                CompareOp::Greater,
                ResidentTemporalValue::Boolean(true),
            ),
            (
                ResidentTemporalValue::ZonedTime {
                    nanos: 12 * HOUR,
                    offset_seconds: 3_600,
                },
                ResidentTemporalValue::ZonedTime {
                    nanos: 11 * HOUR,
                    offset_seconds: 0,
                },
                CompareOp::Greater,
                ResidentTemporalValue::Boolean(true),
            ),
            (
                ResidentTemporalValue::ZonedTime {
                    nanos: 12 * HOUR,
                    offset_seconds: 3_600,
                },
                ResidentTemporalValue::ZonedTime {
                    nanos: 11 * HOUR,
                    offset_seconds: 0,
                },
                CompareOp::Eq,
                ResidentTemporalValue::Boolean(false),
            ),
            (
                ResidentTemporalValue::LocalDateTime {
                    seconds: -1,
                    nanos: 999_999_998,
                },
                ResidentTemporalValue::LocalDateTime {
                    seconds: -1,
                    nanos: 999_999_999,
                },
                CompareOp::Less,
                ResidentTemporalValue::Boolean(true),
            ),
            (
                ResidentTemporalValue::ZonedDateTimeFixedOffset {
                    seconds: 0,
                    nanos: 0,
                    offset_seconds: 3_600,
                },
                ResidentTemporalValue::ZonedDateTimeFixedOffset {
                    seconds: 0,
                    nanos: 0,
                    offset_seconds: 0,
                },
                CompareOp::Less,
                ResidentTemporalValue::Boolean(true),
            ),
            (
                ResidentTemporalValue::ZonedDateTimeNamed {
                    seconds: 0,
                    nanos: 7,
                    timezone: "Europe/Paris".into(),
                },
                ResidentTemporalValue::ZonedDateTimeNamed {
                    seconds: 0,
                    nanos: 7,
                    timezone: "Europe/Paris".into(),
                },
                CompareOp::Eq,
                ResidentTemporalValue::Boolean(true),
            ),
        ];
        for (left, right, operation, expected) in cases {
            assert_eq!(
                evaluate_resident_temporal_comparison(&left, &right, operation)?,
                expected
            );
        }
        Ok(())
    }

    #[test]
    fn duration_equality_uses_normalized_canonical_components_and_has_no_order() -> Result<()> {
        let values = execute(
            vec![
                text(ResidentTemporalValueFunction::Duration, "PT60S"),
                text(ResidentTemporalValueFunction::Duration, "PT1M"),
                comparison(ResidentTemporalValueFunction::Duration, CompareOp::Eq, 0, 1),
                text(ResidentTemporalValueFunction::Duration, "P1M"),
                text(ResidentTemporalValueFunction::Duration, "P30D"),
                comparison(ResidentTemporalValueFunction::Duration, CompareOp::Eq, 3, 4),
                comparison(
                    ResidentTemporalValueFunction::Duration,
                    CompareOp::Less,
                    3,
                    4,
                ),
            ],
            vec![2, 5, 6],
        )?;
        assert_eq!(
            values,
            [
                ResidentTemporalValue::Boolean(true),
                ResidentTemporalValue::Boolean(false),
                ResidentTemporalValue::Null,
            ]
        );
        Ok(())
    }

    #[test]
    fn fixed_and_named_zoned_datetime_labels_convert_exactly() {
        let fixed =
            resident_temporal_value_scalar(&ResidentTemporalValue::ZonedDateTimeFixedOffset {
                seconds: 1,
                nanos: 2,
                offset_seconds: 3_661,
            });
        assert_eq!(
            fixed,
            Some(ScalarValue::ZonedDateTime {
                seconds: 1,
                nanos: 2,
                timezone: Arc::from("+01:01:01"),
            })
        );
        let negative =
            resident_temporal_value_scalar(&ResidentTemporalValue::ZonedDateTimeFixedOffset {
                seconds: 1,
                nanos: 2,
                offset_seconds: -1_800,
            });
        assert_eq!(
            negative,
            Some(ScalarValue::ZonedDateTime {
                seconds: 1,
                nanos: 2,
                timezone: Arc::from("-00:30"),
            })
        );
        let named = resident_temporal_value_scalar(&ResidentTemporalValue::ZonedDateTimeNamed {
            seconds: 3,
            nanos: 4,
            timezone: "America/St_Johns".into(),
        });
        assert_eq!(
            named,
            Some(ScalarValue::ZonedDateTime {
                seconds: 3,
                nanos: 4,
                timezone: Arc::from("America/St_Johns"),
            })
        );
        assert_eq!(
            resident_temporal_value_scalar(&ResidentTemporalValue::ZonedDateTimeFixedOffset {
                seconds: 0,
                nanos: 0,
                offset_seconds: 86_400,
            }),
            None
        );
    }
}

#[cfg(test)]
mod temporal_row_cpu_tests {
    use super::*;
    use crate::{
        Layer, NodeId,
        backend::{
            BackendKind, ResidentExecutionId, ResidentNodeBinding, ResidentRowInstruction,
            ResidentRowOperation, ResidentRowProgram, ResidentRowProgramManifest,
            ResidentRowSortKey,
        },
        graph::{GraphStore, IndexCatalog, NodeInput},
    };

    const PROJECT: ProjectId = ProjectId(uuid::Uuid::nil());

    fn scan_input(label: LabelId, rows: usize, project: ProjectId) -> ResidentNodePipelineRequest {
        ResidentNodePipelineRequest {
            project,
            labels: vec![label],
            layers: LayerMask::OBSERVED,
            initial_optional: false,
            expansion: None,
            continuations: Vec::new(),
            correlated_optional: None,
            relationship_null_filter: None,
            predicates: Vec::new(),
            property_filters: Vec::new(),
            value_matrix: None,
            mutation: None,
            orders: Vec::new(),
            offset: 0,
            limit: usize::MAX,
            integer_projections: Vec::new(),
            property_null_projections: Vec::new(),
            max_output_rows: rows,
        }
    }

    fn request(
        graph: &GraphStore,
        bookmark: Bookmark,
        label: LabelId,
        seed: u64,
        value_type: ResidentRowValueType,
        operation: ResidentRowOperation,
    ) -> Result<ResidentRowProgramRequest> {
        let program = ResidentRowProgram {
            instructions: vec![ResidentRowInstruction {
                output_type: value_type,
                operation,
            }],
        };
        let sort_keys = vec![ResidentRowSortKey {
            register: 0,
            descending: false,
            nulls_first: false,
        }];
        let final_registers = vec![0];
        let manifest = ResidentRowProgramManifest::build(
            &program,
            &sort_keys,
            0,
            usize::MAX,
            4,
            &final_registers,
            seed * 10,
        )?;
        Ok(ResidentRowProgramRequest {
            project: PROJECT,
            expected_bookmark: bookmark,
            expected_graph_revision: graph.revision(),
            expected_layout_version: graph.layout_version(),
            execution: ResidentExecutionId { high: 1, low: seed },
            input: scan_input(label, 4, PROJECT),
            program,
            manifest,
            sort_keys,
            offset: 0,
            limit: usize::MAX,
            max_output_rows: 4,
            final_registers,
        })
    }

    fn scalar_duration_request(
        graph: &GraphStore,
        bookmark: Bookmark,
        seed: u64,
        column: ResidentRowColumn,
        months: i64,
        days: i64,
        seconds: i64,
        nanos: i32,
    ) -> Result<ResidentRowProgramRequest> {
        let rows = column.len();
        let output_type = column.value_type();
        let program = ResidentRowProgram {
            instructions: vec![
                ResidentRowInstruction {
                    output_type,
                    operation: ResidentRowOperation::InputColumn(column),
                },
                ResidentRowInstruction {
                    output_type,
                    operation: ResidentRowOperation::TemporalAddDuration {
                        temporal: 0,
                        months,
                        days,
                        seconds,
                        nanos,
                    },
                },
            ],
        };
        let sort_keys = Vec::new();
        let final_registers = vec![1];
        let manifest = ResidentRowProgramManifest::build(
            &program,
            &sort_keys,
            0,
            usize::MAX,
            rows,
            &final_registers,
            seed * 10,
        )?;
        Ok(ResidentRowProgramRequest {
            project: PROJECT,
            expected_bookmark: bookmark,
            expected_graph_revision: graph.revision(),
            expected_layout_version: graph.layout_version(),
            execution: ResidentExecutionId { high: 2, low: seed },
            input: ResidentNodePipelineRequest {
                project: PROJECT,
                labels: Vec::new(),
                layers: LayerMask::OBSERVED,
                initial_optional: false,
                expansion: None,
                continuations: Vec::new(),
                correlated_optional: None,
                relationship_null_filter: None,
                predicates: Vec::new(),
                property_filters: Vec::new(),
                value_matrix: None,
                mutation: None,
                orders: Vec::new(),
                offset: 0,
                limit: usize::MAX,
                integer_projections: Vec::new(),
                property_null_projections: Vec::new(),
                max_output_rows: rows,
            },
            program,
            manifest,
            sort_keys,
            offset: 0,
            limit: usize::MAX,
            max_output_rows: rows,
            final_registers,
        })
    }

    #[test]
    fn constant_duration_arithmetic_preserves_temporal_shapes_and_nulls() -> Result<()> {
        let graph = GraphStore::default();
        let bookmark = Bookmark {
            term: 1,
            index: graph.revision(),
        };
        let image = ResidentProjectImage::build(
            PROJECT,
            bookmark,
            &graph,
            &TemporalStore::default(),
            &IndexCatalog::default(),
        )?;
        let mut cpu = CpuBackend::new(128 * 1024 * 1024, 8 * 1024 * 1024);
        cpu.admit_project(image)?;

        let cases = [
            (
                ResidentRowColumn::Date {
                    // 2020-01-31 and a deliberately non-zero hidden NULL payload.
                    days: vec![18_292, 99],
                    validity: vec![1, 0],
                },
                (1, 0, 0, 0),
                ResidentRowColumn::Date {
                    // Calendar month clipping produces 2020-02-29.
                    days: vec![18_321, 0],
                    validity: vec![1, 0],
                },
            ),
            (
                ResidentRowColumn::LocalTime {
                    nanos: vec![86_399_500_000_000, 42],
                    validity: vec![1, 0],
                },
                (0, 0, 1, 750_000_000),
                ResidentRowColumn::LocalTime {
                    nanos: vec![1_250_000_000, 0],
                    validity: vec![1, 0],
                },
            ),
            (
                ResidentRowColumn::ZonedTime {
                    nanos: vec![86_399_500_000_000, 42],
                    offset_seconds: vec![3_600, 99],
                    validity: vec![1, 0],
                },
                (0, 0, 1, 750_000_000),
                ResidentRowColumn::ZonedTime {
                    nanos: vec![1_250_000_000, 0],
                    offset_seconds: vec![3_600, 0],
                    validity: vec![1, 0],
                },
            ),
            (
                ResidentRowColumn::LocalDateTime {
                    // 2020-01-31T23:59:59.900000000.
                    seconds: vec![1_580_515_199, 42],
                    nanos: vec![900_000_000, 99],
                    validity: vec![1, 0],
                },
                (1, 1, 1, 200_000_000),
                ResidentRowColumn::LocalDateTime {
                    // 2020-03-02T00:00:01.100000000.
                    seconds: vec![1_583_107_201, 0],
                    nanos: vec![100_000_000, 0],
                    validity: vec![1, 0],
                },
            ),
            (
                ResidentRowColumn::ZonedDateTime {
                    seconds: vec![1_600_000_000, 42],
                    nanos: vec![900_000_000, 99],
                    timezone_offsets: vec![0, 12, 12],
                    timezone_bytes: b"Europe/Paris".to_vec(),
                    validity: vec![1, 0],
                },
                (0, 0, 0, 200_000_000),
                ResidentRowColumn::ZonedDateTime {
                    seconds: vec![1_600_000_001, 0],
                    nanos: vec![100_000_000, 0],
                    timezone_offsets: vec![0, 12, 12],
                    timezone_bytes: b"Europe/Paris".to_vec(),
                    validity: vec![1, 0],
                },
            ),
        ];
        for (index, (column, (months, days, seconds, nanos), expected)) in
            cases.into_iter().enumerate()
        {
            let request = scalar_duration_request(
                &graph,
                bookmark,
                index as u64 + 1,
                column,
                months,
                days,
                seconds,
                nanos,
            )?;
            let result = cpu
                .execute_row_program(&request, &CancellationToken::new())?
                .validate(&request, BackendKind::Cpu)?;
            assert_eq!(result.source_positions(), [0, 1]);
            assert_eq!(result.projected_columns()[0].column, expected);
            assert_eq!(result.scratch_bytes(), request.scratch_bytes(2)?);
        }
        Ok(())
    }

    #[test]
    fn stored_temporal_properties_load_sort_and_publish_exact_tuples() -> Result<()> {
        let mut graph = GraphStore::default();
        let label = graph.catalog_mut().intern_label("Temporal")?;
        let date = graph.catalog_mut().intern_property("date")?;
        let local_time = graph.catalog_mut().intern_property("local_time")?;
        let zoned_time = graph.catalog_mut().intern_property("zoned_time")?;
        let local_datetime = graph.catalog_mut().intern_property("local_datetime")?;
        let zoned_datetime = graph.catalog_mut().intern_property("zoned_datetime")?;
        let hour = 3_600_i64 * 1_000_000_000;
        for row in 0..4_u64 {
            let properties = match row {
                0 => vec![
                    (date, ScalarValue::Date(2)),
                    (local_time, ScalarValue::LocalTime(9)),
                    (
                        zoned_time,
                        ScalarValue::ZonedTime {
                            nanos: 12 * hour,
                            offset_seconds: 7_200,
                        },
                    ),
                    (
                        local_datetime,
                        ScalarValue::LocalDateTime {
                            seconds: 10,
                            nanos: 1,
                        },
                    ),
                    (
                        zoned_datetime,
                        ScalarValue::ZonedDateTime {
                            seconds: 10,
                            nanos: 0,
                            timezone: "UTC".into(),
                        },
                    ),
                ],
                1 => vec![
                    (date, ScalarValue::Date(-1)),
                    (local_time, ScalarValue::LocalTime(1)),
                    (
                        zoned_time,
                        ScalarValue::ZonedTime {
                            nanos: 11 * hour,
                            offset_seconds: 0,
                        },
                    ),
                    (
                        local_datetime,
                        ScalarValue::LocalDateTime {
                            seconds: 9,
                            nanos: 999_999_999,
                        },
                    ),
                    (
                        zoned_datetime,
                        ScalarValue::ZonedDateTime {
                            seconds: 9,
                            nanos: 999_999_999,
                            timezone: "UTC".into(),
                        },
                    ),
                ],
                2 => vec![
                    (date, ScalarValue::Date(0)),
                    (local_time, ScalarValue::LocalTime(5)),
                    (
                        zoned_time,
                        ScalarValue::ZonedTime {
                            nanos: 11 * hour,
                            offset_seconds: 3_600,
                        },
                    ),
                    (
                        local_datetime,
                        ScalarValue::LocalDateTime {
                            seconds: 10,
                            nanos: 0,
                        },
                    ),
                    (
                        zoned_datetime,
                        ScalarValue::ZonedDateTime {
                            seconds: 10,
                            nanos: 0,
                            timezone: "Europe/London".into(),
                        },
                    ),
                ],
                _ => Vec::new(),
            };
            graph.insert_node(NodeInput {
                id: NodeId(100 + row),
                layer: Layer::Observed,
                revision: row + 1,
                labels: vec![label],
                properties,
            })?;
        }
        let bookmark = Bookmark {
            term: 1,
            index: graph.revision(),
        };
        let image = ResidentProjectImage::build(
            PROJECT,
            bookmark,
            &graph,
            &TemporalStore::default(),
            &IndexCatalog::default(),
        )?;
        let mut cpu = CpuBackend::new(128 * 1024 * 1024, 8 * 1024 * 1024);
        cpu.admit_project(image)?;

        let binding = ResidentEntityBinding::Node(ResidentNodeBinding::Start);
        let cases = [
            (
                ResidentRowValueType::Date,
                ResidentRowOperation::LoadDateProperty {
                    binding,
                    property: date,
                },
                vec![1, 2, 0, 3],
                ResidentRowColumn::Date {
                    days: vec![-1, 0, 2, 0],
                    validity: vec![1, 1, 1, 0],
                },
            ),
            (
                ResidentRowValueType::LocalTime,
                ResidentRowOperation::LoadLocalTimeProperty {
                    binding,
                    property: local_time,
                },
                vec![1, 2, 0, 3],
                ResidentRowColumn::LocalTime {
                    nanos: vec![1, 5, 9, 0],
                    validity: vec![1, 1, 1, 0],
                },
            ),
            (
                ResidentRowValueType::ZonedTime,
                ResidentRowOperation::LoadZonedTimeProperty {
                    binding,
                    property: zoned_time,
                },
                vec![2, 0, 1, 3],
                ResidentRowColumn::ZonedTime {
                    nanos: vec![11 * hour, 12 * hour, 11 * hour, 0],
                    offset_seconds: vec![3_600, 7_200, 0, 0],
                    validity: vec![1, 1, 1, 0],
                },
            ),
            (
                ResidentRowValueType::LocalDateTime,
                ResidentRowOperation::LoadLocalDateTimeProperty {
                    binding,
                    property: local_datetime,
                },
                vec![1, 2, 0, 3],
                ResidentRowColumn::LocalDateTime {
                    seconds: vec![9, 10, 10, 0],
                    nanos: vec![999_999_999, 0, 1, 0],
                    validity: vec![1, 1, 1, 0],
                },
            ),
            (
                ResidentRowValueType::ZonedDateTime,
                ResidentRowOperation::LoadZonedDateTimeProperty {
                    binding,
                    property: zoned_datetime,
                    maximum_timezone_bytes: 13,
                },
                vec![1, 2, 0, 3],
                ResidentRowColumn::ZonedDateTime {
                    seconds: vec![9, 10, 10, 0],
                    nanos: vec![999_999_999, 0, 0, 0],
                    timezone_offsets: vec![0, 3, 16, 19, 19],
                    timezone_bytes: b"UTCEurope/LondonUTC".to_vec(),
                    validity: vec![1, 1, 1, 0],
                },
            ),
        ];
        for (index, (value_type, operation, expected_positions, expected_column)) in
            cases.into_iter().enumerate()
        {
            let request = request(
                &graph,
                bookmark,
                label,
                index as u64 + 1,
                value_type,
                operation,
            )?;
            let result = cpu
                .execute_row_program(&request, &CancellationToken::new())?
                .validate(&request, BackendKind::Cpu)?;
            assert_eq!(result.source_positions(), expected_positions);
            assert_eq!(result.projected_columns()[0].column, expected_column);
        }

        let understated_timezone_width = request(
            &graph,
            bookmark,
            label,
            6,
            ResidentRowValueType::ZonedDateTime,
            ResidentRowOperation::LoadZonedDateTimeProperty {
                binding,
                property: zoned_datetime,
                maximum_timezone_bytes: 12,
            },
        )?;
        let error = cpu
            .execute_row_program(&understated_timezone_width, &CancellationToken::new())
            .expect_err("understated timezone admission metadata must fail closed");
        assert_eq!(error.code, ErrorCode::GpuAdmissionFailure);
        Ok(())
    }
}

#[cfg(test)]
mod procedure_table_cpu_tests {
    use std::sync::Arc;

    use ordered_float::OrderedFloat;

    use super::*;
    use crate::execution::{ProcedureDefinition, ProcedureField, ProcedureValueType, ResultValue};
    use crate::{ResidentExecutionId, ResidentExecutionObligation};

    fn string(value: &str) -> ResultValue {
        ResultValue::Scalar(ScalarValue::String(Arc::from(value)))
    }

    fn integer(value: i64) -> ResultValue {
        ResultValue::Scalar(ScalarValue::Integer(value))
    }

    fn float(value: f64) -> ResultValue {
        ResultValue::Scalar(ScalarValue::Float(OrderedFloat(value)))
    }

    fn null() -> ResultValue {
        ResultValue::Scalar(ScalarValue::Null)
    }

    fn request(
        definition: &ProcedureDefinition,
        arguments: Vec<ResultValue>,
        maximum_output_rows: usize,
        execution_low: u64,
    ) -> Result<ResidentProcedureTableRequest> {
        ResidentProcedureTableRequest::new(
            definition.resident_table()?,
            arguments,
            ResidentExecutionId {
                high: 0x5052_4f43,
                low: execution_low,
            },
            ResidentExecutionObligation {
                id: execution_low
                    .checked_add(1)
                    .ok_or_else(|| Error::internal("test obligation identity overflow"))?,
                kind: ResidentObligationKind::Procedure,
                scope: ResidentObligationScope::ProcedureTable,
            },
            maximum_output_rows,
        )
    }

    fn execute_rows(request: &ResidentProcedureTableRequest) -> Result<Vec<u32>> {
        let cpu = CpuBackend::new(16 * 1024 * 1024, 0);
        assert!(cpu.supports_native_procedure_table());
        let validated = cpu
            .execute_procedure_table(request, &CancellationToken::new())?
            .validate_for_publication(request, BackendKind::Cpu)?;
        assert_eq!(
            validated.completion(),
            ResidentDeviceCompletion::CpuReference
        );
        assert_eq!(validated.table_fingerprint(), request.table_fingerprint());
        assert_eq!(validated.request_fingerprint(), request.fingerprint()?);
        Ok(validated.into_selected_source_rows())
    }

    #[test]
    fn cpu_procedure_table_matches_nullable_utf8_number_variants_and_multiple_rows() -> Result<()> {
        let definition = ProcedureDefinition::new(
            "test.lookup",
            vec![
                ProcedureField::new("name", ProcedureValueType::String, true)?,
                ProcedureField::new("number", ProcedureValueType::Number, true)?,
            ],
            vec![ProcedureField::new(
                "answer",
                ProcedureValueType::String,
                false,
            )?],
            vec![
                vec![string("Malmö"), integer(1), string("integer")],
                vec![string("Malmö"), float(1.0), string("float")],
                vec![string("東京"), integer(1), string("utf8")],
                vec![null(), null(), string("nullable")],
            ],
        )?;

        assert_eq!(
            execute_rows(&request(
                &definition,
                vec![string("Malmö"), integer(1)],
                4,
                1,
            )?)?,
            [0, 1]
        );
        assert_eq!(
            execute_rows(&request(
                &definition,
                vec![string("東京"), float(1.0)],
                4,
                2,
            )?)?,
            [2]
        );
        assert_eq!(
            execute_rows(&request(&definition, vec![null(), null()], 4, 3)?)?,
            [3]
        );

        const EXACT_INTEGER: i64 = 9_007_199_254_740_993;
        const ADJACENT_FLOAT: f64 = 9_007_199_254_740_992.0;
        let exact_numbers = ProcedureDefinition::new(
            "test.exactNumber",
            vec![ProcedureField::new(
                "number",
                ProcedureValueType::Number,
                false,
            )?],
            Vec::new(),
            vec![vec![integer(EXACT_INTEGER)], vec![float(ADJACENT_FLOAT)]],
        )?;
        assert_eq!(
            execute_rows(&request(
                &exact_numbers,
                vec![integer(EXACT_INTEGER)],
                2,
                4,
            )?)?,
            [0]
        );
        assert_eq!(
            execute_rows(&request(&exact_numbers, vec![float(ADJACENT_FLOAT)], 2, 5,)?)?,
            [1]
        );
        Ok(())
    }

    #[test]
    fn cpu_procedure_table_canonicalizes_signed_zero_and_never_matches_nan() -> Result<()> {
        let definition = ProcedureDefinition::new(
            "test.floatEdges",
            vec![ProcedureField::new(
                "number",
                ProcedureValueType::Number,
                false,
            )?],
            Vec::new(),
            vec![vec![float(0.0)], vec![float(-0.0)], vec![float(f64::NAN)]],
        )?;

        let signed_zero = request(&definition, vec![float(-0.0)], 3, 6)?;
        let ResultValue::Scalar(ScalarValue::Float(value)) = &signed_zero.arguments()[0] else {
            panic!("signed-zero fixture changed type")
        };
        assert_eq!(value.into_inner().to_bits(), 0.0_f64.to_bits());
        assert_eq!(execute_rows(&signed_zero)?, [0, 1]);
        assert!(execute_rows(&request(&definition, vec![float(f64::NAN)], 3, 7)?)?.is_empty());
        Ok(())
    }

    #[test]
    fn cpu_procedure_table_preserves_unit_relation_and_fails_closed_on_output_budget() -> Result<()>
    {
        let unit = ProcedureDefinition::new("test.unit", Vec::new(), Vec::new(), Vec::new())?;
        assert_eq!(unit.row_count(), 1);
        assert_eq!(execute_rows(&request(&unit, Vec::new(), 1, 8)?)?, [0]);

        let repeated = ProcedureDefinition::new(
            "test.repeated",
            vec![ProcedureField::new(
                "key",
                ProcedureValueType::String,
                false,
            )?],
            Vec::new(),
            vec![vec![string("same")], vec![string("same")]],
        )?;
        let bounded = request(&repeated, vec![string("same")], 1, 9)?;
        let cpu = CpuBackend::new(16 * 1024 * 1024, 0);
        let error = cpu
            .execute_procedure_table(&bounded, &CancellationToken::new())
            .expect_err("CPU procedure selection must not truncate to its output budget");
        assert_eq!(error.code, ErrorCode::ResultBudgetExceeded);
        Ok(())
    }
}
